window.POEM_DB=window.POEM_DB||{};POEM_DB["song_038"]={"n":"释正觉","dyn":"宋","poems":[{"t":"与白表白","f":"七言绝句","c":["密室分灯光焰焰，空壶著月影沈沈。","谁言古殿今无佛，只在其时来梵音。"]},{"t":"与杲侍者","f":"七言绝句","c":["道吾当年不肯道，渐源中路没商量。","先师灵骨今犹在，无用扶锹上法堂。"]},{"t":"与法上人南谷过黄氏居 其二","f":"七言绝句","c":["乱石深云寻野泉，老侬怪我地行仙。","钟情山水醇于酒，今夜竹床成醉眠。"]},{"t":"与法上人南谷过黄氏居 其一","f":"七言绝句","c":["淡烟苍树水溅溅，黄氏初平已得仙。","满地痴羊不收拾，夕阳零乱绕篱眠。"]},{"t":"与简禅人","f":"七言绝句","c":["虚明道洗壮心秋，畦服蒙颅下板头。","定起要看星汉兔，回机失却雪山牛。"]},{"t":"大功不宰","f":"七言绝句","c":["吾家消息默中看，看处虚明霁月寒。","一色是功须转却，石霜端要髑髅乾。"]},{"t":"大明庵留偈","f":"七言绝句","c":["略彴横门下转流，挂窗山在屋檐头。","大明古意是时节，霜夜月堂帘上钩。"]},{"t":"小师慧果驰书取雪峰真歇和尚","f":"七言绝句","c":["鸟窠闲口聊吹布，雪老低头却入庵。","生死同条末后句，也应千里问同参。"]},{"t":"门里出身","f":"七言绝句","c":["无位真人赤肉团，大千沙界著毛端。","明明不借他家事，用处全功祇个般。"]},{"t":"丹霞忌日","f":"七言绝句","c":["明月清风霁景凉，华鲸喷雪水茫茫。","灵然一点谁人委，怀抱千年作夜光。"]},{"t":"五王子 内生","f":"七言绝句","c":["妙龄天嗣自重瞳，尊贵威严镇六宫。","规步从来不出禁，阍人祇得颂芳风。"]},{"t":"五王子 化生","f":"七言绝句","c":["丝纶传得出宸帏，宣花春城类莫齐。","妙握当途无字印，马蹄终不染尘泥。"]},{"t":"五王子 末生","f":"七言绝句","c":["甘分清孤守固穷，衡门寥落正西风。","一鸣便是苍梧凤，不意飘流鸥鹭中。"]},{"t":"五王子 诞生","f":"七言绝句","c":["星攒金殿降生时，称体宫衣覆雪肌。","功就转身全合父，光中潜拨玉轮移。"]},{"t":"古上人出丐求颂","f":"七言绝句","c":["化门到处大千身，古鉴无尘谷有神。","方信相随混不得，堂堂独露是何人。"]},{"t":"四宾主 主中主","f":"七言绝句","c":["不动金轮万德全，宸苔含月未排班。","当头讳字寰中禁，谁敢依稀犯圣颜。"]},{"t":"四宾主 主中宾","f":"七言绝句","c":["御楼吹角六街明，金马将军出禁城。","阃外化权良有准，不伤风物致升平。"]},{"t":"四宾主 宾中主","f":"七言绝句","c":["不恋经商利万金，晚来古路问家音。","分明得报尊亲健，争奈难平喜惧心。"]},{"t":"四宾主 宾中宾","f":"七言绝句","c":["平生心事结眉头，满面风埃鬓已秋。","大底出门无伎术，奈何今日路贫愁。"]},{"t":"四料简 人境两俱夺","f":"七言绝句","c":["罢奏笙篁夜欲阑，银河光浸紫微寒。","星移月暗无消息，客散云楼酒椀乾。"]},{"t":"四料简 人境俱不夺","f":"七言绝句","c":["十分花事属歌喉，笑入芳尘烂漫游。","皇道太平无忌讳，纵横何处不风流。"]},{"t":"四料简 夺人不夺境","f":"七言绝句","c":["懒问谁持造化权，门前春事正暄妍。","雨晴花色明如锦，风暖莺声滑似弦。"]},{"t":"四料简 夺境不夺人","f":"七言绝句","c":["厌馀客路忽思家，鬓发春饶尽雪华。","月底路歧通著脚，归心未稳隔烟霞。"]},{"t":"玉壶阁颂","f":"七言绝句","c":["风霜磨洗秋空清，月浴星河分外明。","默默玉壶中自照，家传清白妙难名。"]},{"t":"全超不借借","f":"七言绝句","c":["霜重风严景寂寥，玉关金锁手慵敲。","寒松尽夜无虚籁，老鹤移栖空月巢。"]},{"t":"因览仰山小释迦语成唱道二首 其二","f":"七言绝句","c":["一念全超旷劫初，玉人端坐白牛车。","往来历尽傍参妙，回首途中物物渠。"]},{"t":"朱干办求颂","f":"七言绝句","c":["磨洗纷尘百念秋，湛然源底未分流。","其间自照因缘外，水净娟娟浮月钩。"]},{"t":"次韵谷书记胜果院绝句","f":"七言绝句","c":["沙风漠漠卷烟湖，默默渔舟似有无。","五老回看更痴绝，渠应怪我得工夫。"]},{"t":"江郎中求颂","f":"七言绝句","c":["净治心地廓无垠，一段光明破夙昏。","拨转机轮分化事，百千三昧见门门。"]},{"t":"应身","f":"七言绝句","c":["双六盘中信彩赢，风行草偃月弯晴。","拦街截巷憨皮袋，弥勒何时不下生。"]},{"t":"时司理求颂","f":"七言绝句","c":["净磨心鉴绝游尘，本际灵明自照神。","个里机回圆历历，化分百亿大千身。"]},{"t":"泐潭云庵偶作","f":"七言绝句","c":["曦色云庵半堵红，霜林初暖鸟啼风。","下知人在萝窗里，瞑目炉薰百虑空。"]},{"t":"身里出门","f":"七言绝句","c":["放旷还来荆棘林，倒骑牛自醉吟吟。","谁嫌烟雨闹蓑笠，祇个虚空不挂针。"]},{"t":"姚道人乞颂","f":"五言绝句","c":["慈悲方便事，触处有工夫。","应变随声色，团团盘走珠。"]},{"t":"宣和甲辰岁开十日予欲束衣随淮水东下锦官常禅人且合掌请语因留三绝 其三","f":"七言绝句","c":["恬然谁作去留心，月下沧波风过林。","相别相逢定何所，明明向道只如今。"]},{"t":"宣和甲辰岁开十日予欲束衣随淮水东下锦官常禅人且合掌请语因留三绝 其一","f":"七言绝句","c":["麓华联蕾破春红，惭愧无私造化功。","谁怕满头椿岁月，要听啼鸟说家风。"]},{"t":"宣和甲辰岁开十日予欲束衣随淮水东下锦官常禅人且合掌请语因留三绝 其二","f":"七言绝句","c":["蔬肠那著一星愁，但觉春眠粥似稠。","梦外寻盟何处是，荻洲稚子绿排头。"]},{"t":"泉州王道友舍簟乞颂","f":"七言绝句","c":["秋入眠床水一方，江湖风月坐来凉。","浮浮爽气仙游去，身在苍烟白鸟行。"]},{"t":"赵学士求颂","f":"七言绝句","c":["身前身后独灵灵，一切如来出此经。","歇尽狂心便相见，水秋天净月亭亭。"]},{"t":"送传道者归省母氏 其一","f":"七言绝句","c":["夜来霜嚇橘脐黄，乞与归人怀冷香。","到日跨门须转却，白头不是本生娘。"]},{"t":"送传道者归省母氏 其二","f":"七言绝句","c":["妙尽功圆转处幽，若人真解倒骑牛。","雨蓑风笠旧行李，适意明明百草头。"]},{"t":"送觉禅人","f":"七言绝句","c":["明月堂虚客不留，衡湘秀处赋清游。","回途复妙无遗影，天水从来一样秋。"]},{"t":"送圆上人之龙舒 其二","f":"七言绝句","c":["道人归作山下宾，霜筇笋屦飘孤云。","到时春满石牛谷，蔬蕨是谁相与分。"]},{"t":"送渊上人","f":"七言绝句","c":["朱丝不用挂烧桐，一曲新丰为送公。","后夜老松风籁静，皋禽不见月巢空。"]},{"t":"送僧归抚州","f":"七言绝句","c":["不肯云林伴冷凄，疏山归谒矮阇梨。","非枯桩句如明白，会要重来摩伏犀。"]},{"t":"送慧禅人往上江籴麻米 其一","f":"七言绝句","c":["石霜拈处最分明，万万千千一粒生。","归日饭香穿鼻吼，相呼作舞下堂行。"]},{"t":"送慧禅人往上江籴麻米 其四","f":"七言绝句","c":["芦华明月水茫茫，激箭风舟破冷光。","亲到庐陵酬米价，那时开口便相当。"]},{"t":"送慧禅人往上江籴麻米 其三","f":"七言绝句","c":["解开篾束肚皮宽，子去谁忧甑釜寒。","云水相迎船到岸，饱丛林事不相瞒。"]},{"t":"送慧禅人往上江籴麻米 其二","f":"七言绝句","c":["云门糊饼赵州茶，里许明明著得些。","公案见成知味底，一千二百衲僧家。"]},{"t":"送慧禅人往上江籴麻米 其五","f":"七言绝句","c":["去去西江趁便风，丁宁底意语庞公。","归来定是通身饭，直下人人识己躬。"]},{"t":"借位明功","f":"七言绝句","c":["六户虚通路不迷，太阳影里不当机。","纵横妙展无私化，恰恰行从鸟道归。"]},{"t":"借借不借借","f":"七言绝句","c":["识尽甘辛百草头，鼻无牵纆得优游。","不知有去成知有，始信南泉唤作牛。"]},{"t":"真身","f":"七言绝句","c":["一叶落时天下秋，不风流处却风流。","木人退步金绳断，直下无机牵铁牛。"]},{"t":"颂古一百则 其六十一","f":"七言绝句","c":["入手还将死马医，反魂香欲起君危。","一朝拶出通身汗，方信侬家不惜眉。"]},{"t":"颂古一百则 其四十一","f":"七言绝句","c":["饵云钩月钓清津，年老心孤未得鳞。","一曲离骚归去后，汨罗江上独醒人。"]},{"t":"颂古一百则 其七十八","f":"七言绝句","c":["胡饼云超佛祖谈，句中无味若为参。","衲僧一日如知饱，方见云门面不惭。"]},{"t":"颂古一百则 其三十七","f":"七言绝句","c":["一唤回头识我不，依俙萝月又成钩。","千金之子才流落，漠漠涂穷有许愁。"]},{"t":"颂古一百则 其三十四","f":"七言绝句","c":["皤然渭水起垂纶，何似首阳清饿人。","只在一尘分变态，高名勋业两难泯。"]},{"t":"颂古一百则 其七","f":"七言绝句","c":["痴儿刻意止啼钱，良驷追风顾影鞭。","云扫长空巢月鹤，寒清入骨不成眠。"]},{"t":"颂古一百则 其一","f":"七言绝句","c":["一段真风见也么，绵绵化母理机梭。","织成古锦含春像，无奈东君漏泄何。"]},{"t":"颂古一百则 其七十二","f":"七言绝句","c":["冻眠雪屋岁摧颓，窈窕萝门夜不开。","寒槁园林看变态，春风吹起律筒灰。"]},{"t":"颂古一百则 其六十三","f":"七言绝句","c":["芥城劫石妙穷初，活眼环中照廓虚。","不许夜行投晓到，家音未肯付鸿鱼。"]},{"t":"颂古一百则 其六十五","f":"七言绝句","c":["新妇骑驴阿家牵，体段风流得自然。","堪笑效颦邻舍女，向人添丑不成妍。"]},{"t":"颂古一百则 其六十","f":"七言绝句","c":["百战成功老太平，优柔谁肯苦争衡。","玉鞭金马闲终日，明月清风富一生。"]},{"t":"颂古一百则 其十五","f":"七言绝句","c":["老觉情多念子孙，而今惭愧起家门。","是须记取南山语，镂骨铭肌共报恩。"]},{"t":"颂古一百则 其二十一","f":"七言绝句","c":["借来聊尔了门头，得用随宜即便休。","象骨岩前弄蛇手，儿时做处老知羞。"]},{"t":"颂古一百则 其二十八","f":"七言绝句","c":["壮志棱棱鬓未秋，男儿不愤不封侯。","翻思清白传家客，洗耳溪头不饮牛。"]},{"t":"颂古一百则 其八十七","f":"七言绝句","c":["藤枯树倒问沩山，大笑呵呵岂等闲。","笑里有刀窥得破，言思无路绝机关。"]},{"t":"颂古一百则 其五十七","f":"七言绝句","c":["不妨行细输先手，自觉心粗愧撞头。","局破腰间斧柯烂，洗清凡骨共仙游。"]},{"t":"颂古一百则 其八十二","f":"七言绝句","c":["出门跃马扫欃抢，万国烟尘自肃清。","十二处亡闲影响，三千界放净光明。"]},{"t":"颂古一百则 其三十九","f":"七言绝句","c":["粥罢令教洗钵盂，豁然心地自相符。","而今参饱丛林客，且道其间有悟无。"]},{"t":"颂古一百则 其六十八","f":"七言绝句","c":["拂牛剑气洗兵威，定乱归功更是谁。","一旦氛埃清四海，垂衣皇化自无为。"]},{"t":"颂古二十一首 其十一","f":"七言绝句","c":["学道须教正眼开，莫将狂解意中猜。","脱鞋龟上人难会，遂使携囊特地来。"]},{"t":"颂古二十一首 其十","f":"五言绝句","c":["杀人不眨眼，救人须出手。","论实不论虚，合升始为斗。"]},{"t":"颂古二十一首 其九","f":"七言绝句","c":["出群须是英灵汉，敌胜还他师子儿。","选佛若无如是眼，假饶千载亦奚为。"]},{"t":"颂古二十一首 其八","f":"七言绝句","c":["侍者来言报大王，赵州曾揖下禅床。","怜儿不觉傍观丑，争奈全身在帝乡。"]},{"t":"颂古二十一首 其五","f":"七言绝句","c":["露地白牛起问端，随缘叱叱齿牙寒。","不知饮啄是何物，吃吃直教沧海乾。"]},{"t":"颂古二十一首 其二","f":"七言绝句","c":["千乡万里寻知己，一语临禨不契梁。","面壁九年居少室，觅心千古累神光。"]},{"t":"偈二首 其二","f":"五言绝句","c":["妄息寂自生，寂生知则现。","知生寂自灭，了了唯真见。"]},{"t":"偈二首 其一","f":"五言绝句","c":["心地含诸种，普雨悉皆萌。","既悟花情已，菩提果自成。"]},{"t":"偈十首 其七","f":"五言绝句","c":["交互明中暗，功齐转觉难。","力穷忘进退，金锁网鞔鞔。"]},{"t":"偈十首 其一","f":"七言绝句","c":["即此见闻非见闻，更无声色可呈君。","个中若了全无事，体用何妨分不分。"]},{"t":"偈颂七十八首 其四十","f":"七言绝句","c":["衲僧须沥髑髅乾，透出威音世外看。","岁月不能迁变处，个人肯共你同盘。"]},{"t":"偈颂七十八首 其四十四","f":"七言绝句","c":["尊贵位中尊贵身，绵绵不断转金轮。","刹尘寿量无穷已，个是乾坤旧主人。"]},{"t":"偈颂七十八首 其四十六","f":"七言绝句","c":["衲僧去就水云姿，偶堕夤缘出应时。","今日又归林壑去，得便宜了得便宜。"]},{"t":"偈颂七十八首 其二十八","f":"七言绝句","c":["一点环中照极微，智无功处却存知。","缘思净尽无馀事，半夜星河斗柄垂。"]},{"t":"偈颂七十八首 其七十一","f":"七言绝句","c":["浪爪拿舟雪溅空，十年胸际著慈风。","如今堂上时相见，分付饮茶谈笑中。"]},{"t":"偈颂七十八首 其三十五","f":"七言绝句","c":["大雄父子许雍容，消息传通到劫空。","寒卧老蟾呼不觉，扶疏丹桂月朦胧。"]},{"t":"偈颂七十八首 其五十九","f":"七言绝句","c":["借婆裙子拜婆年，买尽风光不著钱。","劈面来时莫回避，个人里许有生缘。"]},{"t":"偈颂七十八首 其四十八","f":"七言绝句","c":["淅淅西风敛气浮，远天野水一般秋。","衲僧歇到兹时节，坐照寒光湛不流。"]},{"t":"偈颂七十八首 其三十七","f":"七言绝句","c":["去时踏雪似来时，来去途中一色迷。","妙得转身宾是主，宗家正令付全提。"]},{"t":"偈颂七十八首 其二十九","f":"七言绝句","c":["脱去还如鸟出笼，水云将与旧来同。","依俙似曲才堪听，又被风吹别调中。"]},{"t":"偈颂七十八首 其二十六","f":"七言绝句","c":["衲僧祇么是家风，隐显磨砻入混融。","归子返掷全归火，羚羊挂角不同功。"]},{"t":"偈颂七十八首 其十三","f":"七言绝句","c":["法界无尘心月圆，本光还照未萌前。","而今直下分明去，犹较南泉二十年。"]},{"t":"偈颂七十八首 其十八","f":"七言绝句","c":["谁将活眼窥空劫，我道宗枝染浩春。","头角峥嵘藏不得，青原门下有祥麟。"]},{"t":"偈颂七十八首 其七十三","f":"七言绝句","c":["一盘黑白互交罗，生杀其中细琢磨。","樵人疑著当头著，不觉腰閒烂斧柯。"]},{"t":"偈颂七十八首 其二十四","f":"七言绝句","c":["寒灰发焰旧家风，恰恰当人受用中。","片雪飞来炉上尽，通身无像不同功。"]},{"t":"偈颂七十八首 其十一","f":"七言绝句","c":["半夜谁传无尽灯，黄梅席上许卢能。","虚明自照非心力，分付丛林了事僧。"]},{"t":"偈颂七十八首 其十七","f":"七言绝句","c":["云敛长空风日和，太平樵牧共高歌。","衲僧饭饱无佗事，密密机前弄玉梭。"]},{"t":"偈颂七十八首 其七十七","f":"五言绝句","c":["本源无风波，真界绝涯畛。","木人步月归，转侧功勋尽。"]},{"t":"偈颂七十八首 其六","f":"七言绝句","c":["一亘清虚夜正央，桂宫老兔冷喷霜。","混融明暗无分处，谁辨个中偏正方。"]},{"t":"偈颂二百零五首 其六十五","f":"七言绝句","c":["功勋密处转身难，转后家风又觉宽。","黯黯旧山青落眼，涣然霜雪洗蓑寒。"]},{"t":"偈颂二百零五首 其一○八","f":"七言绝句","c":["萧然一念未萌初，露柱怀胎辨得无。","风扫馀云月未上，霁虚廓净绝方隅。"]},{"t":"偈颂二百零五首 其四十五","f":"七言绝句","c":["去时还复似来时，明月芦华夜不迷。","转棹又归何处去，秋光目断水天低。"]},{"t":"偈颂二百零五首 其一九九","f":"七言绝句","c":["一灯分耀百千灯，个事宗家谁也曾。","少室相传断臂可，黄梅分付坠腰能。"]},{"t":"偈颂二百零五首 其十八","f":"七言绝句","c":["劫火炎炎是事灰，劫空空处有灵台。","更无妍丑成痕垢，妍丑俱从个里来。"]},{"t":"偈颂二百零五首 其一一一","f":"七言绝句","c":["凡圣通同共一家，寂光田地看生涯。","而今选佛心空去，自有丘园开觉华。"]},{"t":"偈颂二百零五首 其二○一","f":"七言绝句","c":["曾到家山里许看，星河濯月霁天寒。","个时失却娘生口，始信从来鼻孔宽。"]},{"t":"偈颂二百零五首 其二十二","f":"七言绝句","c":["柳线垂金莺语滑，华棚张锦蝶飞忙。","见闻里许通消息，谁得先生点铁方。"]},{"t":"偈颂二百零五首 其一六三","f":"楚辞体","c":["须知风动心摇树，果见云生性起尘。","雨霖霖兮日杲杲，点头弥勒解分身。"]},{"t":"偈颂二百零五首 其五","f":"七言绝句","c":["来来去去山中人，识得青山便是身。","青山是身身是我，更于何处著根尘。"]},{"t":"偈颂二百零五首 其一九七","f":"七言绝句","c":["清白传家雪月光，玉壶中有转身方。","情乾识尽功勋断，不觉全身入帝乡。"]},{"t":"偈颂二百零五首 其一七一","f":"七言绝句","c":["老大丛林快说禅，不将禅拄口皮边。","谷深山远空无像，何处人呼应不圆。"]},{"t":"偈颂二百零五首 其一二七","f":"七言绝句","c":["一枝秀出栴檀林，想见馨香慰众心。","不负老兄开凿力，当风子和鹤鸣阴。"]},{"t":"偈颂二百零五首 其一四二","f":"七言绝句","c":["轻烟羃羃衲僧家，节物迎春气象华。","流水落华无限意，游山消息付长沙。"]},{"t":"偈颂二百零五首 其一二八","f":"七言绝句","c":["影略门前倒刹竿，个中消息授传难。","玲珑侍者能相委，盘走明珠珠走盘。"]},{"t":"偈颂二百零五首 其一三九","f":"七言绝句","c":["明月芦华四望连，转身人上合同船。","借功自有旁参事，历历机头看正偏。"]},{"t":"偈颂二百零五首 其十四","f":"七言绝句","c":["开炉岁岁是今朝，暖气潜通称我曹。","可惜丹霞烧木佛，翻令院主堕眉毛。"]},{"t":"偈颂二百零五首 其二十五","f":"词","c":["衲僧舌头真个自由，浑仑里许没锥钩。","轮扁斲工不授子，庖丁游刃无全牛。"]},{"t":"偈颂二百零五首 其一八四","f":"七言绝句","c":["莫向枯龟版上钻，衲僧开口见心肝。","莲华荷叶出未出，做尽工夫转觉难。"]},{"t":"偈颂二百零五首 其三十八","f":"七言绝句","c":["直到劫空明自己，有无不堕超生死。","夜船载月钓沧浪，清白传家只如此。"]},{"t":"偈颂二百零五首 其九十一","f":"七言绝句","c":["苏秦尝佩六国印，许由还厌一瓢风。","了无佗相能通变，可笑僧繇画志公。"]},{"t":"偈颂二百零五首 其二○○","f":"七言绝句","c":["闻说英雄苦战争，四方歧路自难行。","而今踏著长安道，始信家邦久太平。"]},{"t":"偈颂二百零五首 其五十一","f":"七言绝句","c":["凛凛将军令已行，八荒四海要澄清。","提来剑气干牛斗，洗荡氛埃见太平。"]},{"t":"偈颂二百零五首 其一一二","f":"七言绝句","c":["三千世界出弹指，百亿庄严集化身。","寿域无疆同道久，河沙劫数一成春。"]},{"t":"偈颂二百零五首 其一七九","f":"七言绝句","c":["泥泥水水一年农，收拾将来碓下舂。","炊软香分千钵饭，肚皮参饱放颓慵。"]},{"t":"偈颂二百零五首 其七十八","f":"七言绝句","c":["吾家日日选场开，及第心空有大才。","莫把桂枝零碎折，为佗和月抱将来。"]},{"t":"偈颂二百零五首 其一九五","f":"七言绝句","c":["香林腊月火烧山，关楗如今透底难。","无碍机锋能自在，虚空挥剑不成瘢。"]},{"t":"偈颂二百零五首 其六十六","f":"五言绝句","c":["空劫威音前，别有一壶天。","御楼观射猎，不是刈茅田。"]},{"t":"偈颂二百零五首 其二十七","f":"七言绝句","c":["华鸟不来空过春，牛头山上懒慵人。","自心净故元无作，放下许多閒苦辛。"]},{"t":"偈颂二百零五首 其一九一","f":"七言绝句","c":["玉女依稀夜动机，锦丝历历吐梭脐。","水天湛碧全功堕，雪月寒清一色迷。"]},{"t":"偈颂二百零五首 其九十七","f":"七言绝句","c":["皓然雪月净无埃，一色功中更放开。","唤起牧童蓑底梦，白牛鼻孔拽教回。"]},{"t":"斜川道上望庐山三绝 其一","f":"七言绝句","c":["真味酣心倚瘦筇，萧骚风啸一蹊松。","无人共语圆通境，笑看云吞石耳峰。"]},{"t":"斜川道上望庐山三绝 其三","f":"七言绝句","c":["水从乌石山前转，人在斜川岸上行。","寂漠柴桑古祠下，我来无酒酹渊明。"]},{"t":"斜川道上望庐山三绝 其二","f":"七言绝句","c":["青山放足溪转腰，蓑翁理网儿摇舠。","先生畴日骑鱼去，岸上人家谁姓陶。"]},{"t":"符十五郎求颂 其二","f":"七言绝句","c":["圆虚里许得真游，离水犀通一点秋。","机应无私登鸟道，妙同明月静随流。"]},{"t":"雪窦中岩夜坐","f":"七言绝句","c":["哀猿叫落中岩月，野客吟残夜半灯。","此景此时谁会得，白云深处坐禅僧。"]},{"t":"善应不触","f":"七言绝句","c":["出门云水任茫茫，相应相酬许当行。","一切时无第二念，雪峰于此谢灵光。"]},{"t":"登清凉三山亭","f":"七言绝句","c":["絮风花雨一春残，未厌兹亭夜倚阑。","隐隐三山抱江月，清凉境界露松寒。"]},{"t":"禅人写真求赞 其六","f":"七言绝句","c":["槁寒初不展家风，默默神游透劫空。","百草头边兴化事，自然秋色水天同。"]},{"t":"嵩山老人告行作六偈送之 其五","f":"七言绝句","c":["服像中情将有得，江湖底事勿相忘。","橘洲白鸟秋成伍，渔火莼羹蓬底香。"]},{"t":"嵩山老人告行作六偈送之 其一","f":"七言绝句","c":["未能老养卧林麓，要乞优恩除发须。","濯足沧浪岁寒事，终来清友石菖蒲。"]},{"t":"嵩山老人告行作六偈送之 其三","f":"七言绝句","c":["嘤嘤鸟鸣如客情，行行柳眼向人青。","投心旧友春成物，汲水前溪月下瓶。"]},{"t":"嵩山老人告行作六偈送之 其二","f":"七言绝句","c":["挽衣苦怪不我住，怀事乞成今乃时。","雷动定知开蛰户，春寒无要勒华枝。"]},{"t":"嵩山老人告行作六偈送之 其四","f":"七言绝句","c":["梦里结忧三变事，觉来还喜一成春。","莺华时节洗衰落，不信馀寒犹著人。"]},{"t":"嵩山老人告行作六偈送之 其六","f":"七言绝句","c":["应缘分影来池月，游世无心出岫云。","适意归来尖屋底，蔬畦还与力锄勤。"]},{"t":"一知殿化佛殿僧堂中灯油求颂","f":"七言律诗","c":["佛灯谁我续光明，果若莲开大梦醒。","香草有心持洁白，兰膏无脚湛寒青。","默耕化外那知夜，真照壶中不觉冥。","家世儿孙传底事，从教辉耀显门庭。"]},{"t":"一禅人化盐求颂","f":"七言律诗","c":["泥沙淘洗浪煎乾，一片照人冰雪寒。","意得试莲浮卤力，默知随箸入蔬盘。","万家婉婉能相助，众口调和信不难。","无像有神聊勘过，圆通眼在舌头端。"]},{"t":"一禅人出丐求颂","f":"七言律诗","c":["一霎山前春雨乾，丛林气韵洗衰寒。","水明玉兔随征棹，线重金鳞上钓竿。","午钵莫嫌分饭甑，千僧无念集蒲团。","化机妙应头头准，手眼通身不著谩。"]},{"t":"十月朔与法上人南谷行 其一","f":"七言律诗","c":["拖策鸣林游兴浓，要将丘壑醉青瞳。","黄华尚媚秋馀日，锦树那禁霜后风。","转岫蛇行岐屈曲，断崖虹卧水丁东。","谁悭剧味平生事，分付饮茶谈笑中。"]},{"t":"上元后二日过谦师庵","f":"七言律诗","c":["横溪一径两山分，深翠茏葱竹日昏。","流水漱冰寒有骨，閒云敛霁雪无根。","应容野毳来投饭，不管春眠往扣门。","窗几薰炉摇篆字，龟床麈语对清温。"]},{"t":"与天池信长老","f":"七言律诗","c":["晚岁丛林闹苇麻，可中著眼辨龙蛇。","行当五路我能事，坐断孤峰渠作家。","佛法从来如嚼蜡，朋俦此去似团沙。","音书不寄思惟尽，千里同风却较些。"]},{"t":"与传道者","f":"七言律诗","c":["残毳编衣裹槁形，胸中底事独醒醒。","亡机冲应用时妙，活眼冷窥虚处灵。","语秀锦云春片段，气清梅雪晓零星。","而今功尽牛头懒，华鸟不来风扫庭。"]},{"t":"与充维那","f":"七言律诗","c":["机梭未动若为颜，一点虚灵入道环。","明月光中窥自己，白云影外到家山。","金鳌转侧夜潮落，玉马嘶鸣春信还。","得手应心无不可，脱然时事岂相关。"]},{"t":"与因典座","f":"七言律诗","c":["胸中行脚事分明，亲见芙蓉缀晚英。","黑马踏霜元不迹，白鱼吹水了无声。","投机曾弄无须锁，出手相扶折脚铛。","去米去沙还未可，要须偏正并头行。"]},{"t":"与孙宣教","f":"七言律诗","c":["作别江头五载馀，海边相访未嫌迂。","山林意与世几绝，丘壑姿逢秋更癯。","约我道耕新活计，辍君诗战老工夫。","儿婚女嫁谁家事，居士有心从马驹。"]},{"t":"与观禅者","f":"七言律诗","c":["豁净虚通入觉场，体前一段本来光。","孤禅恰恰如担板，默照明明似面墙。","秋光芦华两岸雪，夜寒桂月一船霜。","迢迢象外行归路，雁字低低正夕阳。"]},{"t":"与李居士","f":"七言律诗","c":["枯禅胸底洗馀纷，一点虚明湛若存。","刹刹尘尘成净土，华华叶叶发灵根。","无心颇肖云为润，有照浑如月破昏。","舒卷纵横俱在我，个人真得总持门。"]},{"t":"与诺侍者","f":"七言律诗","c":["梦回茶碗手亲扶，雅意沩山转道枢。","自唤主人酬一诺，谁违尊者应三呼。","死生到日还能否，辜负当年是有无。","妙得古人行履处，了无些事作工夫。"]},{"t":"与辅禅人","f":"七言律诗","c":["方游捋遍虎髭须，空劫壶中探有无。","风月满头功未转，江山入骨病难扶。","针投芥粒机非爽，弦续鸾胶道不枯。","归去丛林看仪羽，丹山出处九包雏。"]},{"t":"与黄道友","f":"七言律诗","c":["人头膏火底心休，来预林俦默默游。","犀晕成时月魄夜，雁行断处霁容秋。","百年分付三椽下，万象峥嵘一指头。","归去懒融无伎俩，庵前华鸟莫相求。"]},{"t":"与楷知仓","f":"七言律诗","c":["米坊能者较些些，七百僧中独作家。","半夜传来衣有据，机前收得镜无瑕。","祖师只么闲舂碓，若子如今莫撒沙。","古井先秋念枯冷，金绳钓出玉虾蟆。"]},{"t":"与福州满禅人","f":"七言律诗","c":["而今别后记丁宁，曹洞家风句未形。","月满凤林寒不梦，年深龟壳灼犹灵。","沈沈莫触蛇头毒，的的须明犀角星。","便与放开聊展手，那时相见望州亭。"]},{"t":"与演侍者","f":"七言律诗","c":["白鸥定怪盟事寒，杖藜投社不多难。","苇风华雪秋著岸，船月蓬霜夜转滩。","丘壑身心徒役梦，江湖臭味赋游般。","它时衣外传来物，唤得回头倒刹竿。"]},{"t":"与辨庵主","f":"七言律诗","c":["夹山钩上得芳鳞，不作当年棒喝嗔。","直向劫前分手眼，端能化外拨机轮。","是须眉底有筋汉，方契寰中无舌人。","彻照自宗知细密，任从天下乐忻忻。"]},{"t":"久上人出丐乞颂","f":"七言律诗","c":["孤禅抖擞起僧毡，挂钵寒藤著瘦肩。","破夜无私看霁月，开华不染出泥莲。","底心众事水云饿，何处人家粥饭缘。","寄语毗耶老居士，相投莫怪唤春眠。"]},{"t":"卫进可寺丞腊月二十九日招我以蔬饭从容胜集其居之西一堂榜曰六湛意六处休复同一湛然且求语因作偈云","f":"七言律诗","c":["风澜未作见灵源，六处亡功体湛存。","诸法性空方得座，一弹指响顿开门。","寒梅篱落春能早，野雪棂窗夜不昏。","万像森罗心印印，根尘超豁妙无痕。"]},{"t":"小师智宽与国清作丐请语","f":"七言律诗","c":["入廛一钵是生涯，来自寒山拾得家。","晓影玉钩萝户月，春丛黄粉蜜房华。","午炊佛土香传鼻，参饱云门饭打牙。","准拟神通何处借，净名居士住毗耶。"]},{"t":"小师慧果丐盐求颂","f":"七言律诗","c":["可中滋味欠些些，成就庐山笋蕨家。","丐事子行黄苇渡，盟心人在白鸥沙。","和羹户户俱煎卤，扫雪村村欲没靴。","味及衲僧初偃月，圆通只个是生涯。"]},{"t":"云上人持钵乞颂","f":"七言律诗","c":["云水千僧共默耕，烦君乞食出山行。","蕨薇夜雨萌寒麓，桃李春风织锦城。","空谷一呼同响应，圆珠众色合光明。","上方此去分香饭，为我先须见净名。"]},{"t":"云上人持钵求颂","f":"七言律诗","c":["云林风雪暮纤纤，滴沥寒声晓断檐。","一点丐心盟杖屦，十分化事入锤钳。","霁光如拭月无碍，华锦落机春不嫌。","百亿分身遍尘刹，见闻萧洒孰相黏。"]},{"t":"以何学士韵示像侍者","f":"七言律诗","c":["茂养高标松抱苓，岁寒姿傲雪霜丁。","萧骚风度山林韵，偃蹇气钟丘壑形。","霁月霁云胸次淡，秋山秋水眼棱青。","磨砖谁问马师语，妙发枯龟一灼灵。"]},{"t":"化上人持钵乞颂","f":"七言律诗","c":["化事而今尽付君，归来还我验儿孙。","诸尘正受盛于钵，一句含胡覆却盆。","别处见人知雪岭，自家吃饭识云门。","底心肯负檀那力，开发真机报施恩。"]},{"t":"心上人乞食求颂","f":"七言律诗","c":["去去之人乞食心，春风浩荡洗丛林。","松蹊香腻糁黄粉，竹坞清癯包玉簪。","炊甑分珠斋钵满，净瓶汲月夜塘深。","归来磨濯光明在，向道尘泥不涴金。"]},{"t":"心知庄求颂","f":"七言律诗","c":["耕云种月自由人，田地分明契券真。","黄独将看炊作饭，白牛今已牧来纯。","钁头活计时时用，物外家风处处亲。","禾黍十分秋可望，饱丛林汉著精神。"]},{"t":"心禅人出丐求颂","f":"七言律诗","c":["将看秋早瘦风林，禾卷黄云副丐心。","妙印手中那外物，虚空胸次不容针。","谁家落甑炊香雪，后夜归船棹软金。","洗足蒲团松石上，绕篱山水有清音。"]},{"t":"方上人持钵乞颂","f":"七言律诗","c":["卷衣破晓下连城，意欲分炊往上方。","僧钵饭归三篾饱，蜂房蜜合百华香。","柳丝莺友调唇滑，云锦人家照眼光。","应变纵横看伎俩，随身干木惯逢场。"]},{"t":"月禅人出丐求颂","f":"五言律诗","c":["一月在诸水，动随来去舟。","分身能恁么，到处恰相投。","湖海堕全璧，鱼龙吞曲钩。","归来端可庆，俱得饱参休。"]},{"t":"月禅人出丐求颂","f":"五言律诗","c":["踏雪到人家，投机的不差。","月魂通水脉，春信入梅华。","去觅炊香许，来宽束篾些。","上方分佛事，先我过毗耶。"]},{"t":"王观察求颂","f":"七言律诗","c":["廓虚深净里头看，一点至灵珠走盘。","默默通身明有眼，尘尘分应妙无瘢。","江湖浩浩月随溜，华木欣欣春入端。","变化鲲鹏是时节，便乘羊角作风抟。"]},{"t":"仙上人出丐求颂","f":"七言律诗","c":["缀钵持来勇入廛，家家行结胜因缘。","三千界重慈悲佛，五百生称忍辱仙。","芳濯丛林春冉冉，明随流水月娟娟。","饱参事与千僧供，洗足蒲团枯木禅。"]},{"t":"出康庐渡江淮山拜诸祖塔道中作","f":"七言律诗","c":["涩舟沙水岸棱棱，岸上春泥深涴藤。","回首康山怀结社，真情祖室事传灯。","子孙亹亹雪庭可，衣钵绳绳舂屋能。","坐照少林墙面意，湛明心地瑩如冰。"]},{"t":"甲寅春之海山雨后访王渊明知县","f":"七言律诗","c":["谁问春泥没履牙，萝门窈窕绿差斜。","幽芳松菊渊明径，深秀溪山摩诘家。","默照佛灯寒不掉，对缘心鉴净无瑕。","仍闻懒甚融居士，庭鸟几番狼藉华。"]},{"t":"立春后五日次本上人韵","f":"七言律诗","c":["雪绕楼栏同楚些，梅将青子柳柔柯。","山林臭味入新语，风月膺胸遵古科。","梦付曲肱春困甚，乞如骈拇老閒何。","雨师雷伯情多妒，收拾陶家壁上梭。"]},{"t":"仲春过龙舒法华山寻诵经道者旧庵","f":"五言律诗","c":["支径入穷谷，来寻道者庵。","梵音今默默，华雨尚毵毵。","夜白月半屋，寒青灯一龛。","梦随歌吹去，借路过江南。"]},{"t":"传上人丐盐求颂","f":"七言律诗","c":["濒海人居不事田，生涯清白是家传。","雷鸣山麓潮横雪，津出泥沙卤泛莲。","冰玉色承熬炼力，蕨薇滋藉合和缘。","舌头妙有圆通眼，坐断丛林五味禅。"]},{"t":"冲禅人与翠山出丐求颂","f":"七言律诗","c":["归去家山雪未消，到时雪后翠棱高。","豁然直下断三际，卓尔个中抽一毫。","化钵不妨游幻海，虚舟何惮驾惊涛。","因缘成熟袖双手，莫学吾家败酒糟。"]},{"t":"华亭顾道友儿女俱出家求颂","f":"七言律诗","c":["儿儿女女著袈裟，留得闲身且在家。","不作丘坑看觉地，当锄荟蘙种昙华。","深藏北斗端能许，吸尽西江始较些。","三界脱然亡影像，净名居士好生涯。"]},{"t":"因览仰山小释迦语成唱道二首 其一","f":"七言律诗","c":["脱尽诸缘空不空，杳无边表喻难同。","须知月蚌肠中物，体取云犀角里通。","建化何妨行鸟道，回途复妙显家风。","太平游子归来也，云鬓霜眉内转功。"]},{"t":"因雪示随行禅者","f":"七言律诗","c":["家家种玉满区区，谁裹烟蓑细步趋。","千里同风休缀缀，十方一色尚拘拘。","梦醒光彩两头断，坐稳身心三际无。","清白传家衲僧事，其间转处看工夫。"]},{"t":"尘上人出丐求颂","f":"七言律诗","c":["轻轻弹指便开门，百亿门前百亿身。","妙应因缘通处处，圆明个事遍尘尘。","华间蜂采黄须蜜，柳上莺传青眼春。","归日相呼满钵饭，一时分付饱参人。"]},{"t":"岁开八日谒西溪真悟讲师","f":"七言律诗","c":["雨华几席自清馨，茗碗初收篆缕青。","柔弄柳条风剪剪，冷濡梅蕊雪星星。","不嫌黄卷闲遮眼，有意微尘破出经。","思大气吞三世佛，儿孙未到败门庭。"]},{"t":"早发宁海寿宁道中过奉化","f":"七言律诗","c":["晓径风香雨阵红，凿崖棱石上梯空。","劝归鸟语春过半，投饭人家日正中。","山怪翠寒台对偶，溪能柔碧剡相通。","杨华便是浮萍草，踪迹又随流水东。"]},{"t":"朱熙载作平阴令八十日致仕而归","f":"七言律诗","c":["勇退归来适旧游，家林禾黍一成秋。","黄芦雪照沙头屋，明月波浮江口舟。","耕道谁从夫子后，逃禅今与老僧俦。","柴桑试问陶彭泽，风味真醇相肖不。"]},{"t":"机禅人出丐求颂","f":"七言律诗","c":["尘刹分身看化机，青烟几处午家炊。","面墙坐照丛林事，持钵丐缘云水饥。","出谷鸟传春次第，漾舟人爱月相随。","归来定有饱参句，笑解枯禅篾肚皮。"]},{"t":"机禅人发心丐田","f":"七言律诗","c":["历历机梭看转旋，衲僧手眼有千千。","将知白雪上方饭，出自黄云负郭田。","溉灌流金溪口月，耕犁卷幕陇头烟。","和泥合水谁家事，参饱元无分外禅。"]},{"t":"次韵传道者且游落星院","f":"七言律诗","c":["风立沙根肤粟顽，冷涵星石水湾湾。","登舟欲济轩窗底，扶槛政疑图画间。","云拭山容苍玉障，日浮江面紫金环。","回头五老相招我，林友无嫌夜扣关。"]},{"t":"次韵真歇和尚圆觉经颂一十四首 其一 大光明藏","f":"七言律诗","c":["衲僧拨转铁牛机，默耀灵通底是谁。","月兔影沉云母地，海禽梦卧珊瑚枝。","韶阳佛法嫌饶舌，鲁祖家风解惜眉。","端坐环中虚白处，纵经尘劫个难移。"]},{"t":"次韵真歇和尚圆觉经颂一十四首 其十 净诸业障菩萨章","f":"七言律诗","c":["證语由来把柄长，重重脱处雪加霜。","众生相在犹流浪，寿命根除自息狂。","退骨龙能将雨去，蜕鳞鲲复得风翔。","郢人斲尽蝇泥也，方见元初鼻孔光。"]},{"t":"次韵真歇和尚圆觉经颂一十四首 其六 弥勒菩萨章","f":"七言律诗","c":["痴根爱种力锄除，一段灵明是旧基。","插草天人深会意，拈华尊者笑开眉。","鱼行大士须珍重，布袋憨僧且伏惟。","处处鼻头相撞磕，唯心境界你谩谁。"]},{"t":"次韵真歇和尚圆觉经颂一十四首 其十三 贤善首菩萨章","f":"七言律诗","c":["陀罗尼句觉皇宣，一略闻名胜施缘。","端见髓心相付嘱，莫将耳口作流传。","顿机做处天飞电，大器任时海纳川。","不是老婆情分切，肯留文字破尼乾。"]},{"t":"次韵真歇和尚圆觉经颂一十四首 其五 金刚藏菩萨章","f":"七言律诗","c":["黄金出矿断前疑，岸走舟安觉所欺。","动目是渠摇湛水，聚萤无我灼须弥。","翳消便见飞华尽，机迅将知击电迟。","识得堆堆庵内主，外魔那得到藩篱。"]},{"t":"次韵真歇和尚圆觉经颂一十四首 其八 威德自在菩萨章","f":"七言律诗","c":["门开三观莫迟留，得路行行到始休。","鉴像照心无所住，楼钟出碍有来由。","顶中具眼如天主，肘后分符似国侯。","应世度生游幻海，月船风棹驾涛头。"]},{"t":"次韵真歇和尚圆觉经颂一十四首 其十四 总颂","f":"七言律诗","c":["木童吟处槁回春，个里庄严功德林。","垂手断崖知路活，藏身空劫忌机沈。","未翻识浪无多子，不挂唇皮有一音。","佛祖契心言迹外，炷香清坐与追寻。"]},{"t":"次韵真歇和尚圆觉经颂一十四首 其十二 圆觉菩萨章","f":"七言律诗","c":["选场随手取标毬，长短期中入社流。","觉后绳绳机自脱，悟来密密类难收。","十分饱足雪山草，一色浑成露地牛。","风扫水天尘翳尽，芦华相照月明秋。"]},{"t":"次韵真歇和尚圆觉经颂一十四首 其七 清净慧菩萨章","f":"七言律诗","c":["觉了前前非处难，而今步步到长安。","色心㳷合无丝路，法性圆融没许般。","个事本来元脱洒，几人到此出颟顸。","妄亡起灭功成也，应笑风幡动刹竿。"]},{"t":"次韵真歇和尚圆觉经颂一十四首 其三 普贤菩萨章","f":"七言律诗","c":["侬家活计本天然，刹刹尘尘见普贤。","犀角一星蟾影透，神珠九曲蚁丝穿。","觉非渐次亡棱缝，幻自消镕得混圆。","妙应通身无向背，古菱花不染媸妍。"]},{"t":"次韵真歇和尚圆觉经颂一十四首 其十一 普觉菩萨章","f":"七言律诗","c":["药病相攻双去难，心华开发自家禅。","天真历历非修證，日用堂堂岂授传。","高步丹霄知得计，止啼黄叶信成权。","底时屑屑行泥滓，可笑蜗牛自涴涎。"]},{"t":"次韵真歇和尚圆觉经颂一十四首 其四 普眼菩萨章","f":"七言律诗","c":["谁从普眼道场来，天帝堂前珠网开。","彻底光明成一段，个中清净绝纤埃。","交罗理事真空观，照破根尘不夜台。","恰恰相应尔时节，陶家壁上起梭雷。"]},{"t":"次韵真歇和尚圆觉经颂一十四首 其九 辩音菩萨章","f":"七言律诗","c":["妙圆单复绝中边，五五机轮互换难。","弦管调来声律合，梭丝织出锦文观。","身心一一能分应，手眼千千不可谩。","似付盐梅岩叟用，和羹无复见咸酸。"]},{"t":"次韵端楞伽与生首座","f":"七言律诗","c":["缚茨枯坐九江东，镜像虚融方寸中。","舜若多身禅夜看，母陀罗臂用时通。","缘生谁兆有非有，寂照自知空不空。","道契观音斯善应，萧萧竹雨杂松风。"]},{"t":"行月大师求颂","f":"七言律诗","c":["霁明夜永月行空，破暗真光默默中。","一点至灵虚且应，十方圆鉴照而冲。","床头炉篆浮寒紫，壁上龛灯对冷红。","个里宗乘消息在，蒲团纸帐旧家风。"]},{"t":"行通善友求颂","f":"七言律诗","c":["明白家风月洗霜，道人寒夜坐绳床。","安身谁效兔三窟，返照自如龟六藏。","疑若蛇弓蟠酒盏，妙同蜂蜜得华房。","默游宛转臻元极，虚廓无涯步大方。"]},{"t":"观知殿化殿堂灯油求颂","f":"七言律诗","c":["广堂清白照蒲团，相续真灯未许残。","寂默无声闲口醭，光明不掉寸心寒。","莲开似对秋波浅，梦觉浑疑晓漏乾。","十法界身流影事，自他交彻镜中看。"]},{"t":"访杨才叔不遇留偈斋舍","f":"七言律诗","c":["呼筇起寂下云居，寒麓回春寻友于。","烟染草芒三径暗，雪晞麦脚一锄濡。","欲求真语涤尘想，那畏峭风生粟肤。","不见诗郎归怅怏，清癯时对石菖蒲。"]},{"t":"访黄给事承往宝陀礼普门大士留偈","f":"七言律诗","c":["泛舟谁畏海门津，丈室来寻彼上人。","麈语欲求青眼旧，友心未爽白头新。","黄家羊卧藩篱晚，梅氏仙游岛屿春。","糊饼馒头看手段，观音妙智在尘尘。"]},{"t":"过虎头岩","f":"七言律诗","c":["空岩俨若虎头苍，云腻岩前草木光。","竹吐锦萌春雨饱，松含黄粉野吹香。","石床蟠足散征倦，道境洗心聊坐忘。","投饭上方兰若去，未能痴学顾长康。"]},{"t":"过般若庵","f":"七言律诗","c":["重轩瘦立曲栏头，岛屿青微冷枕流。","望眼解随沙水转，赏心真与岸云浮。","平分野色连延屋，点破江光相趁舟。","般若空宗深得义，森罗元不碍人休。"]},{"t":"齐上人发心知罗汉堂求颂","f":"七言律诗","c":["修结僧缘清净因，青油白茗与乌薪。","庞眉五百圣尊者，行脚一千吾上人。","云屋芳姿开菡萏，地炉煖气卧麒麟。","睡魔不至蒲禅稳，自照光明默默神。"]},{"t":"馀姚胡氏绣观音求颂","f":"七言律诗","c":["线蹊密密度金针，一一针针观世音。","妙净庄严成相好，光明感应发身心。","江横练色月浮水，雨灌华枝春在林。","闻见可中超有路，普门处处许相寻。"]},{"t":"初禅人持钵求颂","f":"七言律诗","c":["佛事潜通兴化门，用时斤斧莫成痕。","全机超出轮回际，一句拔除生死根。","凉吹洗磨烦袂暑，素蟾排逐夜台昏。","鹅王引饮唯醇味，水乳斯分不我浑。"]},{"t":"别五祖山悦众","f":"七言律诗","c":["东山聚散亦夤缘，华吐芳姿柳锁烟。","肯处根尘非一一，用时手眼恰千千。","塔中祖有相传事，岭外人元不会禅。","后日能来圆此话，未嫌敲枕唤春眠。"]},{"t":"别陆尚书","f":"七言律诗","c":["千里同风德不孤，心秋觉月照空壶。","两头坐断何生死，一点圆明异有无。","木马寒嘶青草坞，泥牛春种白云区。","见闻佛事谁迎背，用处全机道转枢。"]},{"t":"别环首座","f":"七言律诗","c":["雪立空庭畴堕宾，丹山握手履芳尘。","石人破晓初移位，玉女羞明却转身。","去意江湖频挂梦，回头棠棣一成春。","丛林衰色待膏沃，侧耳风霆起蛰鳞。"]},{"t":"别觉知藏","f":"七言律诗","c":["一从豆颗爆寒灰，头角峥嵘顶目开。","碧玉盘中珠宛转，琉璃殿上月徘徊。","木人顾影当明去，石女披云半夜来。","偏正功圆须转位，入廛垂手类难该。"]},{"t":"别满首座","f":"七言律诗","c":["丹山凤窟冷相依，惭愧如今羽翼齐。","云外翔鸣同颉颃，林间啄步暂分携。","玉华衔处天容晓，珠树栖时月影低。","引喙醴泉期后会，殆将新语濯尘泥。"]},{"t":"妙禅人出丐求颂","f":"七言律诗","c":["劫壶浩浩洗魔缘，妙处真观自见前。","的的未萌明宾际，灵灵无得入深禅。","风抟海运鲲将蜕，月皎沙寒鹭不眠。","触事投谐能转变，何妨大浪驾空船。"]},{"t":"妙慧上人求颂","f":"七言律诗","c":["妙中有慧独醒醒，历历机前自照灵。","老兔梦寒眠净魄，真犀心醉得通星。","道游刹刹参诸佛，智破尘尘出大经。","顽石点头挥麈尾，坐间华雨一番馨。"]},{"t":"应禅人开田求颂","f":"七言律诗","c":["飘飘捉杖出烟萝，行丐身心遽许多。","针鼻细中投玉线，机头密处度金梭。","应缘片片云成雨，分照团团月在波。","底意周旋便回首，旧巢寒卧雪林柯。"]},{"t":"应禅人出丐求颂","f":"七言律诗","c":["应身随处见尘尘，能顺因缘不背真。","树上虎头呈伎俩，毛端师子显精神。","平生自许得游刃，投老难传知斲轮。","香气满城燂钵饭，丛林一洗浩然春。"]},{"t":"怀上人出丐求颂","f":"七言律诗","c":["胡床拥毳怯春寒，怀丐人行野雪乾。","风信入华披锦段，月魂堕水濯金盘。","净名取饭亡多力，慈氏开门只一弹。","妙得其中佛受用，头头成见不相瞒。"]},{"t":"投食山家","f":"七言律诗","c":["霜晨藜杖起孤禅，乞食山家图省缘。","斜径顺风鸣竹火，飞甍迷眼映松烟。","秋羹木鳖有真味，午饭树鸡无俗膻。","谁谓客床卧不稳，我无支遁买山钱。"]},{"t":"折桂章首座近自双泉来因作句与之","f":"七言律诗","c":["家林稳卧一巢云，厌作梁家庵底宾。","折桂手舒寒触月，衔珠眼合梦游春。","庭除不见雨华鸟，麋鹿能来呼谷神。","五老芳邻归问讯，笑谈相对白头新。"]},{"t":"拟石牛与悟上人","f":"七言律诗","c":["阿牛纯热不鞭牵，卧向古源苍树边。","春谷玉田看去种，雪山香草饱来眠。","背头隆骨任丰载，鼻底流津大作川。","异路行行哮吼处，莫忘露地未萌前。"]},{"t":"时禅人出丐求颂","f":"七言律诗","c":["老能碓下米无舂，一出相烦作变通。","阵阵香风看稻熟，番番时雨见年丰。","手携拍板傅大士，杖挂剪刀梁志公。","妙应群机真绝待，秋清河淡月行空。"]},{"t":"来上人干延寿院乞颂","f":"七言律诗","c":["披蓁卜筑古林阿，百丈心于老病多。","照彻有无方得我，缘分生灭不干他。","谷云冷抱松根石，山月明悬屋角萝。","若子殷勤圆此话，毗耶城里问维摩。"]},{"t":"纯白禅人求颂","f":"七言律诗","c":["明月芦华未得如，清光自照本来虚。","十方坐断须拈帽，一色功圆要放锄。","转背石人归位后，抬头玉马过关初。","尘尘刹刹见身相，方信曹山井觑驴。"]},{"t":"良禅人干田求颂","f":"七言律诗","c":["良田一片望无涯，旷古相传佛祖家。","四至町畦谁作伴，中心树子自开华。","示人镰样秋云卷，催牯鞭声春日斜。","收拾归来付耕事，衲僧气味较些些。"]},{"t":"还南麓旧居。","f":"七言律诗","c":["枝藤结伴得游娱，怀习难宁寻旧居。","云水梦思孤榻稳，山林眼味四窗虚。","秋衣未絮怯繁雨，午饭无盐甘软蔬。","老境端来偿底志，道同巢鸟与渊鱼。"]},{"t":"周秀才出家求颂","f":"七言律诗","c":["标心脱帽法丹霞，借力堂前刬草些。","塞上不须嗟失马，杯中端欲断疑蛇。","久怀甘露濯尘骨，将意丛林开觉华。","古渡雪芦明月共，一壶秋色属吾家。"]},{"t":"和禅人发心丐开海田","f":"七言律诗","c":["檀度夤缘约远寻，利他方称出家心。","丐行端取丛林饱，耕缛不嫌泥水深。","地面丕平春种玉，波痕清浅月浮金。","栽田博饭吾家事，一段风规得老琛。"]},{"t":"宗禅人出丐求颂","f":"七言律诗","c":["万指生涯一钵归，丛林宗尚默无机。","道耕自信我寒槁，妙用相烦君发挥。","薜荔藩篱秋蔓衍，女萝窗户月依稀。","时时处处通消息，物象都卢入范围。"]},{"t":"雨夜宿龙门晓登灵光台礼佛眼塔","f":"七言律诗","c":["一跃龙门适旧怀，棱棱浪级向人开。","洗尘云阵浇华雨，借力天衢破蛰雷。","略彴驾溪桃水满，浮屠瘗骨玉山颓。","欲知佛眼无遮障，须到灵光不夜台。"]},{"t":"雨晴偶作示禅者","f":"七言律诗","c":["快雨快晴寒食近，峥嵘芳事趁佳辰。","弄风柳絮疑成雪，满地榆钱买得春。","雷吐英英茶爪露，暖班茁茁蕨拳伸。","桃华眼闹随蝴蝶，谁似灵云识故人。"]},{"t":"亮禅人持钵求颂","f":"五言律诗","c":["家林一锡飞，炊处青烟微。","严默起禅板，虚通转化机。","溪寒秋染色，月冷夜流辉。","莫学西山亮，此行宜早归。"]},{"t":"保福传化士乞颂","f":"七言律诗","c":["梅福仙游井汲枯，而今云水稳禅蒲。","青原门下藏麟角，黄檗床头捋虎须。","学子柏庭寒立雪，檀家饭甑软炊珠。","乞归将意丛林煖，松食荷衣良槁癯。"]},{"t":"南麓新居","f":"七言律诗","c":["山麓水滨竹木阴，我侬懒养静居深。","一生自足淡中味，三际那收閒底心。","壑云未成出岫意，松风能作下滩音。","十分清兴与谁共，想有沃洲支道林。"]},{"t":"显禅人求颂","f":"五言律诗","c":["显处机须隐，忙时智自閒。","泥牛初出海，玉马复临关。","寒水澄涵月，流云静倚山。","回途分化柄，不作旧家悭。"]},{"t":"津禅人出化盏橐乞颂","f":"七言律诗","c":["吃茶去语落诸方，聚首商量柄杷长。","相席是渠能打令，同尘输尔解和光。","舌头狤獠明无骨，鼻孔累垂暗有香。","盏橐成来圆此话，侬家受用恰平常。"]},{"t":"珊知浴求颂","f":"七言律诗","c":["妙触宣明不洗尘，楞严会上悟心人。","潜鳞窟宅半篙水，枯木形骸一杓春。","涓滴量同法界性，发毛垢净虚空身。","南园应问聊弹指，用处绵绵谷有神。"]},{"t":"荣上人发心知罗汉堂办茶油事乞颂","f":"七言律诗","c":["这开梦觉底因缘，佛佛心同亡后先。","一点灵明三世外，十分妙净万机前。","琢磨自得丛林下，游戏何妨百草颠。","尘刹纵横俱化事，起家人只奋空拳。"]},{"t":"退天童上太守吴学士","f":"七言律诗","c":["三椽五合不求馀，汩汩营营笑拙疏。","妄立是非徒喻马，乐同彼此解观鱼。","洗霜骨出山宜瘦，答响神藏谷应虚。","莫涴人间名字垢，身云心月本如如。"]},{"t":"送广禅人","f":"七言律诗","c":["温风促客下云岭，触处无心即道游。","得坐会当明变豹，出门须解倒骑牛。","冲烟筇入青萝径，载月船回白鸟洲。","中外夷犹功迹绝，㳷然天水一成秋。"]},{"t":"送从上人驰书至京西","f":"七言律诗","c":["衲帔蒙头自照人，月明堂上转机轮。","肯传千里鹡鸰语，要作十分棠棣春。","雪岭同风当日事，石头束篾旧时麟。","家林归卧长连稳，满眼清光不见身。"]},{"t":"送元上人过长芦","f":"七言律诗","c":["阿祖江滨插苇枝，丛林蕃茂果臻斯。","师门昆仲知名旧，缘法东西得面迟。","沙上盟寒鸥怪晚，屋头字草雁来时。","月明古渡清铺练，千里同风不隔丝。"]},{"t":"送仝座主归上党 其一","f":"七言律诗","c":["月兔含清欲喷霜，客怀陈习作归翔。","虽云扫尽名言垢，我笑熏成知见香。","聚石为徒头易点，悟空能讲义难量。","到家握麈随宜说，莫对馀机挥界方。"]},{"t":"送仝座主归上党 其二","f":"七言律诗","c":["觉海长鲸作蜕翔，青天端以背磨光。","胸中浩浩吞云梦，眉际津津秀太行。","静榻每来成友语，孤筇它往咽人肠。","后将访我先传雁，为薙别来三径荒。"]},{"t":"送仝座主归上党 其三","f":"七言律诗","c":["夜明帘外月天霜，衲子还家机事忘。","枯木吟云须内照，死蛇含毒更堤防。","闻琴起舞饮光习，放镜迷头演若狂。","好是重来斲蝇翼，祖师鼻孔要生光。"]},{"t":"送平禅人归鄂渚","f":"七言律诗","c":["浮舟春水作归征，家有良田可饭羹。","久客回翔云一点，旧巢卧看月三更。","人猜我住尖头屋，尔去谁扶折脚铛。","为问岩头穷鬼子，当时何似此时生。"]},{"t":"送修街坊出丐","f":"七言律诗","c":["海上鳌峰裹绮霞，梅仙朋旧有生涯。","清眠梦落三山月，和气吹成一县华。","去驾风舟寻长者，来分甑饭入吾家。","待君归扫馀疑膜，杯影垂弓不是蛇。"]},{"t":"送通禅者之襄阳","f":"七言律诗","c":["疏巢凄冷卧西柯，梦觉归思遽许多。","风雨江头乱雁字，家山坞外悬渔蓑。","白杨村落庞居士，青石浮图蕴大哥。","倦倚苍松坐凉夕，兔推明月下星河。"]},{"t":"送缘上人持钵","f":"七言律诗","c":["缘丐人间一锡飞，苍岩烟腻雪初晞。","风丝未许闹禅眼，云锦将看落化机。","自勉丛林供食钵，谁嫌尘土翳征衣。","归来僧饱上方饭，相伴春山歌采薇。"]},{"t":"送嵩上人住庵 其三","f":"七言律诗","c":["烧痕笋蕨富登春，谁解看承庵内人。","天供异华功未尽，龙吟枯木病难泯。","夜禅终作寒蝉蜕，昼卧何妨倦鸟伸。","后日重来勘诸祖，阿谁钩上赤梢鳞。"]},{"t":"送嵩上人住庵 其二","f":"七言律诗","c":["禅腹须来竹篾缠，好看水牯自耕田。","布单不卖三千里，树耳谁疑二十年。","一句合头尊旅会，十方坐断正偏圆。","它时投杖来相访，且莫穷忙空竖拳。"]},{"t":"送僧归豫章省亲","f":"七言律诗","c":["宾茧风枝梦不宁，夜堂思对老人星。","一心归去事萱草，千里相求鸣鹡鸰。","树树丹枫金堕叶，丛丛黄叶雪浮汀。","西山秀骨濯秋雨，窗户卷帘分远青。"]},{"t":"圆禅者求颂","f":"七言律诗","c":["枯歇身心百不思，湛圆自照劫空时。","妙明智鉴那留垢，虚廓灵机未度丝。","的的髑髅看活眼，堂堂尘刹用閒眉。","是须恁么承当去，鼻孔累垂识祖师。"]},{"t":"恭鉴二禅人干浴镬求颂 其一","f":"七言律诗","c":["大冶镕金入范看，不嫌口阔肚皮宽。","得来妙触通身眼，净放光明赤肉团。","衲子落成俱受赐，檀那相助许投干。","底心试问楞严友，道契圆通只个般。"]},{"t":"恭鉴二禅人干浴镬求颂 其二","f":"七言律诗","c":["范金为镬沸兰津，分付楞严会上宾。","妙触宣明渠具眼，纤尘不受我通身。","投谐冷暖浑忘水，迎合温和似得春。","炉鞴相催成底器，量吞云梦可斯人。"]},{"t":"晖禅人丐盐求颂","f":"七言律诗","c":["庐山淡薄已多时，谁与丛林洗败姿。","为爱海冰资菜味，不嫌春雨破华枝。","仙陀婆事行行辨，舜若多身处处宜。","快意截流船到岸，江头风顺看樯旗。"]},{"t":"浮舟下淮访龟山禅师","f":"七言律诗","c":["霜风猎猎扫平野，沙头蓁翳净如燖。","淮津斜转龟山麓，云汉微分雁塔尖。","篱落梅梢春点点，庭除松影月纤纤。","禅家况是不羁友，问讯勤来想未嫌。"]},{"t":"浮舟之昌国谒韩克明知县","f":"五言律诗","c":["南风帆腹饱，半夜渡沧津。","鲸海漾新月，仙山寻故人。","浪寒千里雪，烟暖十洲春。","来就昌黎语，良惭我效颦。"]},{"t":"海上人知浴求颂","f":"七言律诗","c":["温温气象半篙津，匏杓调和冷煖匀。","直得通身浑是水，端知赤肉了无尘。","风埃面目揩磨净，丘壑形骸洗濯春。","妙触宣明佛子住，首楞严会有斯人。"]},{"t":"称上人干造延寿院乞颂","f":"七言律诗","c":["丛林百丈有清规，特设堂安老病师。","隐几虚心还自照，炷香孤坐绝他思。","妙穷正念空三世，净洗馀昏月一墀。","底意欲从何处问，毗耶居士饱相知。"]},{"t":"航海之宝陀访真歇师兄 其二","f":"七言律诗","c":["得得来寻真歇兄，孤舟扬楫顺潮行。","重联断雁云中字，远赴閒鸥沙上盟。","新味清油燣紫菜，古方淳蜜渍黄菁。","海山只个供盘箸，一段家风不世情。"]},{"t":"航海之宝陀访真歇师兄 其一","f":"七言律诗","c":["至人亲见古观音，化迹今居海上岑。","烟机外分青嶂骨，水天中见白云心。","潮痕拥岸棱棱雪，月魄浮波烂烂金。","根境一如能所断，圆通游践法门深。"]},{"t":"颂古一百则 其六十二","f":"楚辞体","c":["第二头分悟破迷，快须攃手舍筌蹄。","功兮未尽成骈拇，智也难知觉噬脐。","兔老冰盘秋露泣，乌寒玉树晓风凄。","持来大仰辨真假，痕玷浑无贵白圭。"]},{"t":"颂古一百则 其九十二","f":"七言律诗","c":["收尽馀怀厌事华，归来何所是生涯。","烂柯樵子疑无路，挂树壶公妙有家。","夜水金波浮桂影，秋风雪阵拥芦花。","寒鱼著底不吞饵，兴尽清歌却转槎。"]},{"t":"颂古一百则 其九十一","f":"七言律诗","c":["照彻离微造化根，纷纭出没见其门。","游神劫外问何有，著眼身前知妙存。","虎啸萧萧岩吹作，龙吟冉冉洞云昏。","南泉点破时人梦，要识堂堂补处尊。"]},{"t":"颂古一百则 其十一","f":"七言律诗","c":["森罗万象许峥嵘，透脱无方碍眼睛。","扫彼门庭谁有力，隐人胸次自成情。","船横野渡涵秋碧，棹入芦花照雪明。","串锦老渔怀就市，飘飘一叶浪头行。"]},{"t":"颂古一百则 其二十","f":"七言律诗","c":["而今参饱似当时，脱尽廉纤到不知。","任短任长休剪缀，随高随下自平持。","家门丰俭临时用，田地优游信步移。","三十年前行脚事，分明辜负一双眉。"]},{"t":"偈十首 其九","f":"七言律诗","c":["一段光明亘古今，有无照破脱情尘。","当头触著弥天过，退步承当特地新。","紫极宫中鸟抱卵，银河浪里兔推轮。","是须妙手携来用，百亿分身处处真。"]},{"t":"偈颂七十八首 其五十五","f":"七言律诗","c":["玉线金针相续难，劫壶空处妙投关。","香林烟暖风排雪，月窟冰寒影转山。","里许借功方得活，那时退位不知闲。","宗家密密绵绵事，布施多人莫要悭。"]},{"t":"偈颂七十八首 其八十","f":"七言律诗","c":["一亘清虚衲子家，十方三世个生涯。","光明照夜触髅眼，消息含春枯木花。","晓色依依云冉冉，天容淡淡月斜斜。","母陀罗臂通身是，今日逢场便攃沙。"]},{"t":"偈颂七十八首 其七十二","f":"词","c":["髑髅前有本来灵，照彻毗卢顶?平。","玉马过关方半夜，木鸡唤月恰三更。","寥寥迹绝全功转，历历光生借位明。","却著弊衣垂化手，合同船子顺流行。"]},{"t":"偈颂七十八首 其三十八","f":"五言律诗","c":["去时不出户，来时不入门。","清癯山有骨，闲澹云无根。","归家奉祖祢，了事还儿孙。","云水通方士，相期报佛恩。"]},{"t":"偈颂七十八首 其六十七","f":"七言律诗","c":["吾家种草古今难，针鼻才分度线端。","混处相期君把手，到时不与汝同盘。","却来大用纵横是，向去全功转侧看。","底事要凭师印可，轮回生死不相干。"]},{"t":"偈颂七十八首 其五十二","f":"五言律诗","c":["空劫有真宗，声前问己躬。","赤穷新活计，清白旧家风。","的的三乘外，寥寥一印中。","却来行异类，万派自朝东。"]},{"t":"偈颂七十八首 其五十","f":"五言律诗","c":["祇个是家风，明明入混融。","江光芦映月，夜色水吞空。","攃手悬崖下，分身万像中。","回涂登鸟道，恰恰是神通。"]},{"t":"偈颂七十八首 其三十","f":"五言律诗","c":["不可以色见，不可以声求。","风定花犹落，鸟啼山更幽。","四衢明自晓，六户冷如秋。","再坐不疑处，杯中弓影浮。"]},{"t":"偈颂二百零五首 其四十三","f":"七言律诗","c":["朔风拂旦吹秋过，时节薄寒宜就火。","拱默威音世外游，放闲枯木堂中坐。","尘劫空时却有家，道环虚处元无我。","灵灵不昧寂而知，衣钵少林分付可。"]},{"t":"偈颂二百零五首 其六十九","f":"五言律诗","c":["密密住其中，灵然空不空。","一牛才饮水，五马不嘶风。","位里亡消息，机头有变通。","三千大千事，弹指入圆融。"]},{"t":"偈颂二百零五首 其十二","f":"七言律诗","c":["万里西来坐少林，灯灯相续至如今。","泥牛斗里同归海，玉线联时妙契针。","未坠绵绵吾祖绪，不忘切切老婆心。","风前一弄无弦曲，会有丛林人赏音。"]},{"t":"偈颂二百零五首 其八","f":"七言律诗","c":["孤筇长作水云游，底事而今放下休。","一点破幽明历历，十分合体冷湫湫。","暗中须透金针穴，转处还藏玉线头。","劫外家风兹日辨，渠侬真与我侬俦。"]},{"t":"偈颂二百零五首 其四十","f":"七言律诗","c":["主中之主天中天，家势金轮万代传。","退步不居尊贵位，借功却作诞生缘。","廓虚印上无瑕垢，明白机头有转旋。","劫数不能知寿量，湛存象外自绵绵。"]},{"t":"偈颂二百零五首 其十三","f":"七言律诗","c":["菩提无树镜非台，虚净光明不受埃。","照处易分雪里粉，转时难辨墨中煤。","鸟归无影树头宿，华在不萌枝上开。","际会风云底时节，寒梭出蛰一声雷。"]},{"t":"偈颂二百零五首 其三十二","f":"七言律诗","c":["九重尊贵位中人，灿灿星图拱北辰。","活计四时调玉烛，家风万世运金轮。","区分群象布淳化，囊括二仪怀至仁。","算数不能穷寿量，南山苍翠镇长春。"]},{"t":"偈颂二百零五首 其八十二","f":"七言律诗","c":["途中久客忆家山，一线蹊通入翠寒。","望处霁云收素练，跨门残月堕金盘。","十虚俱殒眼方阔，三世齐吞肚觉宽。","变化鲲鹏底时节，霄程九万看风抟。"]},{"t":"偈颂二百零五首 其九十八","f":"七言律诗","c":["阴阳爻象此为宗，杀活机头看变通。","玉女退身功后位，木人引步异中同。","一尘不受能虚廓，万像无遗却混融。","借得因缘成现用，玲珑八面尽家风。"]},{"t":"偈颂二百零五首 其三十五","f":"七言律诗","c":["祖华五叶发灵根，端的知恩解报恩。","大仰未忘东寺会，玄沙相继雪峰存。","机梭传处难通路，针芥投时有妙门。","鼻孔放光出气快，当年一斲尽泥痕。"]},{"t":"宿覆船山阻雨","f":"七言律诗","c":["枝筇同到覆船巅，暂寄筇枝借榻眠。","山水钩帘知属我，烟霞腻枕梦游仙。","觉来笋窟投蔬箸，閒把华房入线编。","想像玲珑岩下雨，春寒犹可卧羊毡。"]},{"t":"寄大洪和尚","f":"七言律诗","c":["饮茶作别出萝门，相送犹怀握手温。","断雁几时归缀字，浮萍随处卧生根。","秋风窗外拥芦雪，梦冷床头堕月魂。","麈柄年来疲转徙，却思红颗共炊盆。"]},{"t":"寄石湫童知县","f":"七言律诗","c":["溪头茅屋远追陶，斗米而今懒折腰。","汉水丈人甘抱瓮，箕山居士厌鸣瓢。","心秋霁月夜相照，鬓雪温风吹不消。","身世曲肱分付梦，蘧随蝴蝶到华条。"]},{"t":"戚泽民从新正日供三僧求颂","f":"七言律诗","c":["君家炊饭办蔬薇，日供畦衣三阿师。","海上浮杯登岸后，云间飞锡过门时。","伊蒲塞作新香气，宾度卢迎老白眉。","施受等心相称可，月随流水下春池。"]},{"t":"清上人持钵求颂","f":"七言律诗","c":["苕霅溪头柳眼青，食时持钵众香城。","诸邻定怪颠毛白，久客自怜心境清。","重念雪寒亲麈语，无忘水暖走鸥盟。","饱丛林汉深相悉，笋蕨春山次第生。"]},{"t":"虚禅人发心丐田","f":"七言律诗","c":["虚廓襟怀作丐游，机缘处处定相投。","开田大义聊舒手，得意忘言暗点头。","白牯耕回山月晓，金刀剪断野云秋。","长连趺坐通身饭，一饱分明百不忧。"]},{"t":"雪晴寄刘殿撰","f":"七言律诗","c":["半毡半幅一羌床，寒淡家风肖老庞。","容易著身藏北斗，等闲开口吸西江。","龛灯梵夹香摇几，茅屋禅蒲雪照窗。","方外友于思对麈，隐人胸次作舂撞。"]},{"t":"普渊行者请颂","f":"七言律诗","c":["脱尽尘机真出家，平持心地是生涯。","法堂刬草堕僧数，舂屋传衣联祖华。","想变石头山下虎，悟空弓影酒中蛇。","寒枯只么清修去，佛种从今却较些。"]},{"t":"景禅人求颂","f":"七言律诗","c":["混处还须转侧看，底时妙在一丝端。","闲云卷雨秋空阔，明月流辉夜水寒。","棹破波光华细碎，梦惊蓬晓影团圞。","真机分应头头准，却出黄芦把钓竿。"]},{"t":"森禅人持钵求颂","f":"七言律诗","c":["森罗万象本同根，个事虚通有化门。","历历当机元不爽，头头大用了无痕。","妙明田地传家祖，参饱丛林委子孙。","缘就归来墙面坐，秋空连水月黄昏。"]},{"t":"游司真洞","f":"七言律诗","c":["桃华濯锦春水寒，洞门窈窕玉勾栏。","三峰拥翠云吞屋，九井扬波雪溅坛。","象帝先身元老语，谷神后事阿谁观。","羽郎清瘦发半白，待乞安期五色丸。"]},{"t":"湛禅人开田求颂","f":"七言律诗","c":["衲僧兹欲起家门，老牯鞭催泥水浑。","混处蹈翻明月影，转时耕断白云根。","力田辛苦遵吾祖，炊饭馨香饱子孙。","底事既归蒲坐稳，湛圆心鉴夙忘痕。"]},{"t":"登云庵","f":"五言律诗","c":["屠苏对碧溪，霜草露幽蹊。","顾我丘壑醉，知谁尘土迷。","萝门窥窈窕，云磴履高低。","猿鸟未相弃，伴人烟树栖。"]},{"t":"登祥云庵谒东林明首座","f":"七言律诗","c":["伐木清哦癖在肠，握筇苍磴履重霜。","玲珑堕壑乳泉响，萧瑟到门松吹香。","高寒夜雨冻一色，虚净晓云流五光。","社散荷枯有遗友，目青须发半沧浪。"]},{"t":"禅人发心干钟乞颂","f":"五言律诗","c":["木落空山霜，夜楼时一撞。","随风度林岭，唤月到萝窗。","响应虚传谷，声飞不碍江。","梦回天意晓，蝴蝶失双双。"]},{"t":"禅人发心丐席求颂 其二","f":"七言律诗","c":["吉祥长者草茸茸，香软登机棱路通。","卷去若人呈己事，得来与我展家风。","默游两岸雪芦外，瘦坐五湖烟水中。","未许春眠梦蝴蝶，大方引步劫壶空。"]},{"t":"禅人发心丐席求颂 其一","f":"七言律诗","c":["万指相从作正观，出求卧席著蒲团。","恬处敛雨野云薄，湛若磨风秋水寒。","卷去犹知鼻头痛，坐来方信髑髅乾。","芦花明月阿谁事，人在江湖把钓竿。"]},{"t":"蒋新臣秀才告别作句送之","f":"七言律诗","c":["雪屋高寒能我过，疏梅清秀雪林柯。","不悭屈宋楚人语，来试宗雷莲社科。","后会说盟如有以，此行洗念入无何。","春风迟立栏干曲，白雪楼前船弄梭。"]},{"t":"谢通讲师五偈 其四","f":"七言律诗","c":["一昨书来约见过，迟留行李未成那。","梨黄枣赤秋如许，发白眉庞老奈何。","相伴采薇云腻袜，不嫌伐木雨濡蓑。","对床默默香摇篆，霁月夜窗悬女萝。"]},{"t":"谢通讲师五偈 其一","f":"七言律诗","c":["得得客来窥大方，松间目击揖归堂。","秋横两眼瞳人碧，云拥三衣栀子香。","夺席胸襟君隗礧，愕邻须发我沧浪。","竹床相对夜深语，河汉濯磨星斗光。"]},{"t":"谢通讲师五偈 其二","f":"七言律诗","c":["五月人间膏火煎，清风麈对有夤缘。","点头顽石能明證，借口虚空解讲玄。","随类佛身分百亿，出尘红卷等三千。","未闲相约蒲禅稳，作别又趋华雨筵。"]},{"t":"谢通讲师五偈 其五","f":"七言律诗","c":["乞食因循答教迟，想能心照未相疑。","三年约友共连璧，千里同风那隔丝。","鞭笋嫩黄出泥土，槿华寒紫裹藩篱。","雨驱暑去晚明霁，来雁门头字脚垂。"]},{"t":"谢通讲师五偈 其三","f":"七言律诗","c":["慰心佛氏未萧条，卓卓缁林有俊髦。","知见香熏舌本利，名言垢净眼棱高。","锦云脚踏冷修月，仙峤牵颓閒钓鳌。","良遂肯从麻谷后，声光矫矫壮吾曹。"]},{"t":"道禅人发心干田乞颂","f":"七言律诗","c":["道人欲乞一囊钱，为我成褫负郭田。","浅水驾牛披晓月，深云下耒破春烟。","力耕妙用吾家事，坐照真机自己禅。","寄语檀那好相助，年年长得饭僧缘。"]},{"t":"勤大师访别作句赠之","f":"七言律诗","c":["若子能来过我门，端知良遂志弥敦。","微尘破处得经卷，万象纷时空眼根。","与世支离谁恶意，怪人棱瘦自秋痕。","归兴定到家林稳，山月流明洗夜昏。"]},{"t":"廓禅人干田求颂","f":"七言律诗","c":["廓虚田地绝蓁荆，望断玉壶冰鉴平。","素色依稀云拥耒，练光片段月分耕。","意为衲子延筇履，力丐檀那助饭羹。","将见金牛笑相唤，丛林气像不多争。"]},{"t":"满化士与圆通大众出丐说偈送之","f":"七言律诗","c":["过门衲子上饶人，破我胡床默味真。","道活髑髅前有地，用冲赤肉上无尘。","盟心芦笋白鸥社，梦眼华枝蝴蝶春。","满著圆通无尽意，四衢处处主中宾。"]},{"t":"蒙禅人丐麦求颂","f":"七言律诗","c":["杖头挂钵丐丹丘，力破清贫一点忧。","红雨几番华事老，黄云万顷麦家秋。","对缘手眼通身是，应物机轮转处幽。","归理韶阳糊饼话，肚皮束篾饱齁齁。"]},{"t":"鉴维那求月堂颂","f":"七言律诗","c":["桂毂谁将玉斧修，风帘收卷许相留。","虚明窗户不知夜，清白身心长濯秋。","鹤梦巢寒松挂壁，鱼惊波动水浮钩。","胡床瘦坐摇香篆，净照壶中一默游。"]},{"t":"端禅人开田乞颂","f":"七言律诗","c":["衲僧田地有来端，底意相携出问檀。","春坞耕开云锦晓，月津划破练光寒。","饱期束肚三条篾，功就移身百尺竿。","恰恰相投看规矩，谷声鉴像一般般。"]},{"t":"题至游庵兼简庵中道友","f":"七言律诗","c":["真实人居遍十方，至游处处露堂堂。","鹅于水器择其乳，蜂在华房采得香。","心鉴照中无垢翳，道环虚里见神光。","能来闹市住三昧，鸟度长空迹不彰。"]},{"t":"题奉化西峰圆觉禅院","f":"七言律诗","c":["水流百折山苍苍，古寺秋容横野航。","明月初濡寒露白，篱花似趁重阳黄。","道人心已老松石，学子胆须磨雪霜。","默默澄源坐兀兀，游鱼沙鸟静相忘。"]},{"t":"别洪山预和尚","f":"五言古诗","c":["般游念未稳，又别住山人。","雁影水中字，云心江上宾。","同条如是住，千里亦成邻。","深翠一枝玺，腐红五合陈。","回途登鸟道，华木故园春。"]},{"t":"十月朔与法上人南谷行 其二","f":"七言律诗","c":["一筇双屦征具简，幽讨胜友宾栖深。","与公半夜丘壑语，慰我平生麋鹿心。","倒榻雅成山水梦，落泉寒作丝桐音。","归欤城寺禅肤粟，定是流想来家林。"]},{"t":"万寿晖长老写师像求赞","f":"楚辞体","c":["空而无痕，绵绵体之若存。","卓而莫群，恰恰用之不勤。","光明破夜月，淡泞出山云。","无得而得，不闻而闻。","少林之传默默，灵山之笑欣欣。","龙雷相送鱼烧尾，豹雾俄披虎炳文。","齐物飘飘兮流梦似随蝴蝶去，亡机荡荡兮清閒还与白鸥分。"]},{"t":"与初禅人","f":"词","c":["洞下家风虚一著，白牛耕断青山脚。","而今何处不逢渠，鼻孔累垂相撞磕。","阿剌剌，始信从来无缚脱。"]},{"t":"与昌国善友","f":"七言律诗","c":["驾潮舟涩岸头沙，得与岩僧款语些。","梦付庄周窗外蝶，疑醒乐广酒中蛇。","夜堂莫怪云悭月，春峤将知雨促华。","想像旧山归去路，照门新锦眼迷家。"]},{"t":"与胨禅人","f":"词","c":["白蘋风作江头秋，青鸟梦随沙水流。","清兴十分蓬上月，满船载入芦华洲。","斯适意，去来休。","六鳌合负归来也，烟浪雪翻收钓钩。"]},{"t":"大宁悟长老写师像求赞","f":"词","c":["眼睛活，髑髅乾，妙在离微转处看。","鱼潜水而秋痕愈碧，鹤卧松而月梦犹寒。","应呼之神居谷，随色之珠走盘。","影响黏谁眉得用，斲泥馀地鼻无漫。"]},{"t":"小师智临禅客写真求赞","f":"楚辞体","c":["云石雪松，岁寒之友从。","晓月霜钟，清白之音容。","自乐也村歌社舞，平怀也牧笛归农。","暴雨卒风，潜神堂而避阵。","吼雷掣电，战禅席而交锋。","十分闲暇，一等疏慵。","青山白云之去就，浮萍流水之行踪。","披雾变文豹，吟云蜕骨龙。","身老艺孤兮难其授子，智齐德半兮未可传宗。"]},{"t":"乌巨光长老写真求赞","f":"楚辞体","c":["骨寒气羸，顶雪颔丝。","牛首之懒，虎头之痴。","兀兀逃禅处，空空选佛时。","九万鹏风扶羊角，千年兔月卧蛾眉。","门门幻起，尘尘智随。","蝴蝶梦游兮庄生齐物，桃华眼冷兮灵云不疑。","初无棱缝，浑莫针锥。","巴陵曾对吹毛剑，珊瑚撑月夜枝枝。"]},{"t":"乌墩密印大师仁公真赞","f":"词","c":["唇口能缄，眉目如笑。","应外而冲，虚中而照。","全身放下是全身，一点独灵常了了。"]},{"t":"五王子 朝生","f":"七言绝句","c":["雄心脱略战文场，端把烟蓑换龙章。","葵藿奉君知贵味，肯怀归去见严光。"]},{"t":"五位 其二","f":"词","c":["偏中正，海云依约神山顶。","归人鬓发白垂丝，羞对秦台寒照影。"]},{"t":"五位 其四","f":"词","c":["兼中至，觌面不须相忌讳。","风化无伤的意玄，光中有路天然异。"]},{"t":"五位 其三","f":"词","c":["正中来，月夜长鲲蜕甲开。","大背摩天振云羽，翔游鸟道类难该。"]},{"t":"五位 其一","f":"词","c":["正中偏，霁碧星河冷浸乾。","半夜木童敲月户，暗中惊破玉人眠。"]},{"t":"五位 其五","f":"词","c":["兼中到，斗柄横斜天未晓。","鹤梦初醒露气寒，旧巢飞出云松倒。"]},{"t":"五祖将禅人求颂","f":"七言律诗","c":["东风吹断濡华雨，淮上秀峰青可数。","束屦欲寻南北山，卷衣又别东西祖。","渊鱼蒲鸟闹一家，汀笋溪蔬甘两箸。","处处相逢记得么，夜寒月在珊瑚树。"]},{"t":"从首座画予于松石间求赞","f":"楚辞体","c":["孤坐默默，倚杖沉沉。","石怀云而无像，松啸风而有音。","应兮珠盘不拨而自转，湛兮玉井随汲而弥深。","诸尘不受兮十分清气，三际无寄兮一片閒心。"]},{"t":"六代祖师画像赞 二祖大祖禅师","f":"词","c":["立雪齐腰，求法断臂。","有志忘诸躯，无心契诸己。","了了常知，其知密微。","妙不借口，的自传衣。","全功归父底时节，拈转虚空绝所依。"]},{"t":"六代祖师画像赞 三祖监智禅师","f":"词","c":["道无拣择，宗非促延。","死生外著，清白家传。","觅罪性空，廓然大同。","妙尽亡能境，机回却借功。","虚明自照靡心识，海月灵犀夜魄通。"]},{"t":"六代祖师画像赞 五祖大满禅师","f":"词","c":["奇女之儿，双峰之嗣。","传衣世称乎妙龄，栽松我愧乎颓齿。","前后两身，古今一心。","孤鸾风舞玻璃镜，长鲸月辗珊瑚林。","钵盂狤獠人将去，几夜舂坊无碓音。"]},{"t":"六代祖师画像赞 六祖大监禅师","f":"楚辞体","c":["广南樵夫，淮西行者。","明珠走盘，黄金出冶。","透影像兮凡圣罔得同尘，续光明兮家世自然不夜。","众星之拱斗之魁，百川之趋海之下。","弃钵袋而逃，提不起而恳招。","非风幡之摇，示即物之情超。","叶落归根兮来时无口，百千三昧兮九牛一毛。"]},{"t":"六代祖师画像赞 四祖大医禅师","f":"楚辞体","c":["授屈眴衣，秉毗卢印。","师坐西山，名称东震。","蜂服之粉兮春蜜之滋，蚌肠之珠兮夜蟾之孕。","远气呈祥，灵枝发旁。","牛头接得融居士，华鸟不来庵外忙。"]},{"t":"六代祖师画像赞 初祖达磨禅师","f":"词","c":["西付不了，东行相讨。","大乘气遥，少林春早。","九年面壁，求人而急。","三拜髓传，得嗣而贤。","芦华明月夜船转，水远天低秋色连。"]},{"t":"王承事写真求赞","f":"楚辞体","c":["苍棱羼颜，璠玙蕴石而辉山。","老节岁寒，琥珀抱松而永年。","威音未兴之际，混沌欲凿之前。","丛林大义兮道尊百丈，刹海平潮兮月现三千。","我为你说法，你为我开田。","据坐松根石头上，知音人信默心传。"]},{"t":"仗锡为长老写真求赞","f":"词","c":["木老春迟，山寒雪早。","潮退珊瑚林，霁空明月晓。","守默自如，对缘恰好。","得往得来，随起随倒。","龙潭觑破天皇，马祖踏著水潦。"]},{"t":"礼三祖智鉴禅师塔","f":"楚辞体","c":["道无拣择，水深山嶷。","祖无出没，月寒天碧。","不萌枝上觉华春，无影树头灵鸟宅。","天柱巍峨兮星河泻清，石牛哮吼兮洞云生白。"]},{"t":"礼大阳明安塔道中得句","f":"五言律诗","c":["佳处轸游念，芒鞋筇杖俱。","溪寒卧虹饿，路暗垂云腴。","冈树鸠呼雨，田家鸡告晡。","此心亮谁语，三绕石浮屠。"]},{"t":"礼五祖大满禅师塔","f":"词","c":["黄梅果熟，白藕花开。","问唯佛性，种异凡胎。","衣传南岭人将去，松老西山我再来。","两借皮囊成底事，一壶风月湛无埃。"]},{"t":"礼四祖大医禅师塔","f":"词","c":["祖道已传，黄梅妙龄。","幻泡忽灭，白净无形。","真相堂堂照膏火，教音默默鸣风铃。","老松挂月寒方夜，冻鹤巢云梦未醒。"]},{"t":"礼投子青禅师塔","f":"楚辞体","c":["塔藏玉骨，云抱山腰。","迹尘外泯，道光内昭。","度金针之玉线，续凤弦之鸾胶。","壶春在而花芳枯木，夜鹤鸣而月浸孤巢。","家风清淡兮石牛饮水，儿孙秀拔兮天柱摩霄。"]},{"t":"光孝恭长老写师像求赞","f":"楚辞体","c":["问者不亲，传者不真。","默成之性，空照而神。","湛存而无像，幽灵而绝邻。","赫炉冶而铸其器，吹风烟而造其春。","建立诸幻，发明至淳。","匠手之挥斤刃利，蝇泥之去鼻端尘。","其斲有信，其受难人。","偃蹇之松兮独扶疏于雪试，臲卼之石兮几破碎于雷瞋。"]},{"t":"再和朱朝奉见寄","f":"五言古诗","c":["朅来林下人，挂冠脱朝绿。","身閒道愈尊，神静碧照目。","落落我就璞，碌碌谁如玉。","欲学陶渊明，高情异浮俗。","白云无定心，青山有奇骨。","肯从莲社宾，共奏无弦曲。","佛生等一念，日劫讵延促。","倾盖同故人，道存聊一瞩。"]},{"t":"成侍者求颂","f":"五言律诗","c":["真源不皱风，月兔影澄水。","枯情但恬如，默默饱禅味。","家风乃廓然，当年第一义。","机轮转有方，万化出弹指。"]},{"t":"次韵传道者过香林","f":"七言律诗","c":["松烟竹蔼细蹊通，清津白石寒珑璁。","艾禅真是甘蔗种，香林再吹薝卜风。","一溪冷引藩篱外，五老秀蹲怀抱中。","写目轩窗意幽远，淡然消息不雷同。"]},{"t":"次韵真歇和尚圆觉经颂一十四首 其二 文殊师利菩萨章","f":"七言律诗","c":["曼殊大士振真风，智洗无明去夙蒙。","眼翳才消华自灭，灵光独照妄还镕。","木人步转初归位，玉女机回却借功。","纲领提持看手段，门门变态是神通。"]},{"t":"次韵超然与折桂觉大师兼简方丈老","f":"五言律诗","c":["束肚三条篾，恬然卧家林。","机深大仰寂，用捷长沙岑。","空壑溪鸣玉，疏筠月漏金。","东山师叔在，此道未浮沈。"]},{"t":"汤寿乡察推写真求赞","f":"楚辞体","c":["形仪潦倒，气貌寒槁。","野云自閒，岩树谁老。","性元静而妙存，体本真而空了。","幻世应诸缘，荒田不拣草。","风烟望断兮鸿影冥冥，天水相连兮秋容渺渺。"]},{"t":"自庐山折桂幡竿原下望彭蠡湖握杖过前山僧舍说偈","f":"五言律诗","c":["木落山骨瘦，水退沙痕隆。","渔舟弄江日，一叶浮软红。","眼底事不俗，道人心若冲。","幡竿头进步，云水展家风。"]},{"t":"过则上人庵","f":"七言律诗","c":["归来萝茑挂烟蓑，钓月耕云倦也那。","山上山下吞佛语，溪东溪西牧牛歌。","廿年树耳亡疑著，一个拳头得用么。","做尽平生闲伎俩，赤鳞无奈瓮齑何。"]},{"t":"别邹秀才","f":"七言律诗","c":["声利明来若梦游，肯迂征家宿云楼。","情高素抱山樊志，性淡幽寻松石俦。","爱我家风清入眼，问伊时事默摇头。","今朝送别还孤坐，空对炉烟篆字浮。"]},{"t":"吴兴辩长老以达磨画像请赞","f":"楚辞体","c":["长芦驾浪，只履西归。","求支那之法器，付屈眴之田衣。","度九年之缄默，印二祖之灵知。","海犀酣月而晕，寒乌带雪而飞。","机前自得兮顶目四照，迷里相逢兮鼻头下垂。","水著秋清兮湖光湛湛，山衔落日兮云锦辉辉。"]},{"t":"吴傅朋郎中书来尝得李伯时所画震旦第一祖西归像相需以赞说偈寄之","f":"楚辞体","c":["其来何求，其去无得。","寂漠度岭兮万里独行，清白传家兮九年一默。","针芥投而妙不可名，毫釐差而敝不可塞。","知过而改，知难而退。","谁去谁来，自买自卖。","当面讳却兮满眼乌华，望涯赞之兮隔身鲸海。"]},{"t":"弟子薄坚仁以幅缣写圆悟禅师像径山裕虎丘隆二高弟侍焉绍兴丙辰二月八日予乞食之苏台过其家且出以相示再三有请辄随喜赞云","f":"楚辞体","c":["力世佛宗，心传我公。","一拳活计，一喝家风。","影草呈机也三圣却瞎，精金出冶也百丈还聋。","绰绰有裕，恢恢而隆。","阿难迦叶之多闻抖擞，目连鹙子之智慧神通。","真得不借之应，大同不宰之功。","百川曲折兮自然到海，万象森罗兮不可逃空。"]},{"t":"张汉乡写真求赞","f":"词","c":["顶覆白雪，眼横碧波。","清霜濡斗柄，古壁挂龙梭。","少林之华未老，曹溪之镜非磨。","所得几何，家传不多。","饱谙云水三条篾，钓尽江湖一片蓑。"]},{"t":"张监税写真求赞","f":"词","c":["幽讨厥初，湛存若虚。","体明无尽，气清有馀。","太行之雪压屋，黄河之冰载车。","豹雾变文之虎，龙雷烧尾之鱼。","风烟濡腻，草木光舒。","根根尘尘了了，法法念念如如。","舂坊行者得衣钵，可信心传不在书。"]},{"t":"报愿慧长老写师像求赞","f":"词","c":["水秋而清，月寒而明。","万机休罢，三际齐平。","尘消却到法身住，幻起还从佛口生。","长天之覆，大地之擎。","诸祖与之同道，众汇与之同行。","龟毛拂而握竖，兔角杖而膝横。","更无一物借来底，招手憨僧作證成。"]},{"t":"灵上人丐盐求颂","f":"七言律诗","c":["熬炼渠经几度难，炎炎炉鞴里头看。","可中皓色从来瑩，直下沧溟吸得乾。","力展家风排淡薄，妙将滋味破辛酸。","道人意满期归也，雪拥茅檐不觉寒。"]},{"t":"邻月堂求颂","f":"七言律诗","c":["畦衣我是出尘人，卜筑高堂与月邻。","床上金刀香剪桂，箧中玉斧冷修轮。","寒癯破梦无嫌病，清白传家不愧贫。","门外潮平船著棹，点头老兔静分身。"]},{"t":"针线贯通","f":"七言律诗","c":["峨峨青山著秋瘦，毛发凋减风骨旧。","白云乃子久相依，清风借力扶出岫。","人间雨足便归来，澹泞寒明同去就。","个中消息妙不传，白云无心青山寿。"]},{"t":"净居照长老写师像求赞","f":"楚辞体","c":["真乘无门兮佛佛道同，面壁有句兮祖祖心空。","静居方外，智入环中。","借功明寂默，借伴入樊笼。","十方周匝，三世混融。","刹刹尘尘齐说法，见闻互换自相通。"]},{"t":"凭宣教写真请赞","f":"词","c":["山林之姿，水月之像。","雷潜九地之中，春在百华之上。","随缘半合半开，分付全收全放。","渊默家风，纵横伎俩。","道超情也万法齐平，心出碍也十方通畅。"]},{"t":"参头智舒与众行者写师像求赞","f":"楚辞体","c":["背鲐齿鲵，皮鸡发鹤。","西北出家，东南行脚。","选佛到空觉觉空，为人除药病病药。","夕壑云生，秋潭月落。","偏正机轮，方圆枘凿。","蝴蝶之春梦栩栩而物齐，白鸥之野盟飘飘而閒乐。","妙触无当，冲应何作。","剑之挥空而彼此不痕，珠之受影而自他相若。","气韵岩稄，音旨拗斡。","跛跛挈挈兮有底迂疏，哆哆和和兮不空罥索。"]},{"t":"宝峰照和尚真赞","f":"楚辞体","c":["山拥云腴，水怀月昼。","照彻体前，湛存身后。","机头梭路微分，针鼻线芒初透。","灵涵万象兮彼不遗馀，坐断十方兮我无渗漏。"]},{"t":"庚子冬二十八日天意晴和与止上人同南麓行横冈转流长作清响阴溪直木寒无悴容到竹林人家饮茶而还","f":"七言律诗","c":["云麓胜处夙未到，清行兴锐忘崎嵚。","谁无瘦杖少扶力，我与幽人同赏心。","壑津软缘自宛转，岸树老碧长阴森。","溪西乞火煮茶去，竹里人家斋磬音。"]},{"t":"治涂田","f":"七言律诗","c":["棋局未散芭蕉仙，樵夫柯烂海成田。","长堤抗潮人得路，淡水没胫牛加鞭。","天云晚晴深似绮，禾稻日茂浓如烟。","白米软炊供众饱，心空选佛石头禅。"]},{"t":"法澄上人出长芦了师兄画像求赞","f":"楚辞体","c":["傲雪松孤，怀云石癯。","妙存而有也不有，独照而无也非无。","万象勿能逃空王之印，众色莫我染灵蛇之珠。","金鸡啼寒兮晓分夜户，玉兔弄魄兮瑩彻冰壶。"]},{"t":"郑成忠写真求赞","f":"词","c":["智不能知，识不能识。","一气轻清，双瞳冷碧。","莲开梦觉，十方虚殒于一时。","鲲蜕鹏抟，九万里成乎一息。","物我普融，自他平出。","珠受色而不痕，剑挥空而何迹。","须更指响，弥勒阁开也许是重深。","尘刹分身，普贤毛孔也初非迫窄。"]},{"t":"郑通判母氏赞","f":"楚辞体","c":["法喜为食，慈悲为舍。","信佛是归，视身如借。","住正念以唯勤，趣外尘而无暇。","机闲万象光中，眼活髑髅眉下。","彼亡也梦蝶露蝉，自得也云犀香麝。","神游真净兮天水同秋，心印妙明兮风月破夜。"]},{"t":"举侍者求颂","f":"五言律诗","c":["秋风濯烦骨，日日觉清省。","相与事枯禅，所养饱正命。","老蟾浴星河，魂魄明耿耿。","真味入谁肠，但知百念冷。"]},{"t":"保福萃长老写师像求赞","f":"词","c":["少食枣而齿黄，老饱盐而瘿亡。","兔分月魄入犀角，蜂采华滋归蜜房。","源深流长，体明用光。","巍巍堂堂，炜炜煌煌。","檀篆香消默无语，乌藤相伴倚绳床。"]},{"t":"南明慧长老写师像求赞","f":"楚辞体","c":["发之白兮苍山雪寒，眼之冷兮远水秋还。","机自转兮夜斗有柄，气自清兮星河无澜。","谷应声而亡像，珠受色而不瘢。","瀛海潮落兮平且净，天宇云收兮虚更宽。","万化起灭兮，默见其端。"]},{"t":"宣和甲辰三月三日山谷寺偶成是时欲下长芦也","f":"五言古诗","c":["温风在山谷，青紫班芳妍。","浩然春公心，不作彼此偏。","其来初无像，荣事亦自然。","云容淡如鹤，草色齐腻烟。","竹萌裹豹裤，蕨茁引儿拳。","盘箸富可喜，齿颊甘亦便。","山水濯尘念，风云会前缘。","苇江怀道人，拥众几两千。","顶门眼照世，胸中海吞川。","同雏丹山巢，羽成各翔迁。","而今欲住集，相见而忘年。","执鞭驱并驾，未愧无綵鞯。","白鸥行作伍，水蔬对烹煎。","抚摩青石牛，不得陪高眠。","将趋皖口市，就买莎郎船。","回首谢诸祖，觉法吾所天。","慧灯耿不夜，心花芳枝联。","后日儿孙辈，莫怪森罗前。"]},{"t":"拜芭蕉情禅师","f":"七言律诗","c":["来谒芭蕉大仰孙，要明圜相识耽源。","横山烟雨洗秋骨，掠面溪风吹暑痕。","菖蒲叶瘦水石秀，枇杷树密轩窗昏。","阿谁床头柱杖子，乞我款曲寻云根。"]},{"t":"春意渐深送客至山麓田舍来往道中复逢法上人因作数语以记所见云 其四","f":"七言绝句","c":["华蹊归来鸟啼暮，庖舍炊烟卧风缕。","西窗旧有竹肋床，伸足曲肱成栩栩。"]},{"t":"春意渐深送客至山麓田舍来往道中复逢法上人因作数语以记所见云 其三","f":"七言绝句","c":["鸟拳花枝作春语，风日焕然晞宿雨。","水肥山翠木欣欣，芳事骈罗不容数。"]},{"t":"春意渐深送客至山麓田舍来往道中复逢法上人因作数语以记所见云 其二","f":"七言绝句","c":["云阵纤纤洗花雨，深竹新闻子规语。","青山白云吾定居，枯肠那著归思虑。"]},{"t":"春意渐深送客至山麓田舍来往道中复逢法上人因作数语以记所见云 其一","f":"七言绝句","c":["青桑柳暗山前路，麦脚含滋一锄雨。","阳林桃是旧家春，冷眼灵云合头语。"]},{"t":"春意渐深送客至山麓田舍来往道中复逢法上人因作数语以记所见云 其五","f":"七言绝句","c":["隔年相逢瘦惊许，风立溪头少时语。","缄情客上钓鱼矶，四面垂云一蓑雨。"]},{"t":"游云栖院作偈与住山琛老禅","f":"七言律诗","c":["紫霄峰顶金浮屠，风铃扬音闹苍虚。","玉栏中地稳行道，云磴下林新葺庐。","江山怀抱富不恶，霜月轩窗清有馀。","老眼寒青伴耶舍，炷香心醉竺仙书。"]},{"t":"送月上人归乡","f":"七言律诗","c":["西风木落山露骨，秋月在水波濯魂。","客意归卧四明麓，三世佛从禅口吞。","大千俱坏我不坏，三六相昏渠不昏。","劫空照见造化种，回首应物亡尘根。"]},{"t":"送明专使","f":"七言律诗","c":["廓落无依合太虚，行行何处不逢渠。","功回冷眼双眉底，照尽横身旷劫初。","大仰默知东寺意，玄沙明上雪峰书。","将归束肚三条蔑，鈯斧相随到处居。"]},{"t":"送金上人之水南","f":"七言律诗","c":["里许由来懒荷担，百草头上何廉纤。","半夜对月笑拍手，不见喷霜三脚蟾。","劫空有句妙如许，公去谁余对眉语。","后见太平堂上师，敢烦为我分明举。"]},{"t":"送圆上人之龙舒 其一","f":"七言绝句","c":["赤头老师无拣择，灊峰染翠吴塘碧。","明明万法入齐观，豁净丝毫元不立。"]},{"t":"送鹿门宗席头","f":"七言律诗","c":["吉祥草织禅家供，一片琉璃滑无缝。","门掩鳞鳞水不流，窗含冉冉云初冻。","坐寒风月蒲芦秋，睡足江湖鸥鸟梦。","而今卷处追昔人，隐隐犹怀鼻头痛。"]},{"t":"送智首座还乡","f":"七言律诗","c":["颠毛垂雪堕清贫，卧久风林梦转身。","一境妙明还就父，六门虚应却来人。","凉秋月兔流魂瑩，湛水云龙蜕骨陈。","家法儿孙须力振，此行未可腐宾宾。"]},{"t":"送嵩上人住庵 其一","f":"七言律诗","c":["世间尘杂长人瘿，归卧萝龛霜月影。","里许离微妙转功，玉壶夜汲琉璃井。","吾家语味嚼枯硬，醉饱回来双眼冷。","云水明明得自由，六门事外谁关屏。"]},{"t":"送照禅人之湖南","f":"楚辞体","c":["衡岳迎秋翡翠瘦，潇湘漾风琉璃皴。","夜船载月急如箭，归去来兮休问津。"]},{"t":"送愿上人归乡","f":"词","c":["溪头买船归鄂渚，一棹清风夜蟾午。","行尽韶山半月程，白云儿就青山父。","岩头老子末后句，此到将知问不语。","无缝塔前风色高，洞然不隔丝毫许。","丁宁此去快须回，吾家之子要全才。","不坐两头明暗路，偏中归去正中来。","阿呵呵，胸次风流知几何。"]},{"t":"借功明位","f":"七言绝句","c":["蘋末风休夜正央，水天虚碧共秋光。","月船不犯东西岸，须信篙人用意良。"]},{"t":"借雪窦韵送超然居士赵表之时在泐潭","f":"七言古诗","c":["一口吸尽西江水，马师家风擢然起。","老庞俯伏嗣芳尘，古也今也谁如此。","超然道与若人交，南游浩意未相饶。","风清骨秀眼寒碧，玉井冰壶冻不消。","羌床孤卧净名室，无住无依脱虚溢。","渊然一默乃全提，不二门开肖当日。","佛事圆来作归想，出门歧路平如掌。","到家儿女独圞头，相对无言得真赏。"]},{"t":"夏安居日过实上人东轩时新竹浴雨因作句歌之","f":"五言古诗","c":["箨龙出丛林，脱锦露新绿。","昂藏引头角，密密均节目。","娟然尘外姿，云雾腻寒玉。","翠满东窗阴，心眼扫恶俗。","虚静颇道情，清癯见风骨。","惠我不老春，为谁无弦曲。","葛陂蛰时事，第恐雷雨促。","不能留高閒，双碧淡相瞩。"]},{"t":"真戒大师求颂","f":"五言律诗","c":["炷香坐羊毡，默默心住禅。","仙桂萌兔窟，神珠媚龙渊。","湛照自家事，出随群动缘。","应机分手眼，不翅有千千。"]},{"t":"真首座写真求赞","f":"楚辞体","c":["觉海元澄，性天廓平。","耳眼空更远，息气细而清。","露寒斗湿，秋淡河横。","丛林底去就，百草头光明。","蛾眉之月兮三千刹海，羊角之风兮九万霄程。","肚皮参饱，肝胆老成。","挥斤容易甚，器受太难生。","为你一斲鼻垩，从教四望人惊。"]},{"t":"能仁仁长老写师像求赞","f":"楚辞体","c":["大圆镜性，平等智心。","老兔卧寒兮清炯炯明月之窟，长鲸?海兮光漾漾珊瑚之林。","千里雪翻波渺渺，百川潮涨水深深。","鹏抟鲲，蜕壳子。","和鹤鸣阴随应还，游刃相逢有赏音。"]},{"t":"能仁翼长老写师像求赞","f":"楚辞体","c":["行脚句亲，住山迹陈。","默有馀味，言还失真。","金发响而出碍，玉雕文以丧纯。","胸中器宇，眉底精神。","虎生三日食牛气，海阔万里吞舟鳞。","性得全提鼻，心传不挂唇。","白雪家庭兮独立腰齐之士，红蕉棋局兮尝观柯烂之人。"]},{"t":"资圣庵欲过圆通","f":"七言律诗","c":["我初浮舟济九江，幽寻兰若山苍厖。","王摩诘画倚栏槛，谢灵运诗开绮窗。","艾禅高谈肖琢玉，法身雅论非枯桩。","梦回便是圆通路，月冷上方钟一撞。"]},{"t":"钱郎中写真求赞","f":"楚辞体","c":["胜净明心，混融古今。","河汉之气清秋阔，牛斗之光寒夜深。","机历历兮锦梭吐绪，道绵绵兮玉线联针。","月漾珊瑚海，春回薝卜林。","法法变通手段，尘尘出碍胸襟。","明镜谁嫌差别像，空山自答合同音。"]},{"t":"颂古一百则 其六十七","f":"词","c":["天盖地载，成团成块。","周法界而无边，折邻虚而无内。","及尽玄微，谁分向背。","佛祖来偿口业债，问取南泉王老师，人人只吃一茎菜。"]},{"t":"颂古一百则 其八十八","f":"词","c":["沧海沥乾，太虚充满。","衲僧鼻孔长，古佛舌头短。","珠丝度九曲，玉机才一转。","直下相逢谁识渠，始信斯人不合伴。"]},{"t":"颂古一百则 其五十","f":"楚辞体","c":["切瑳琢磨，变态肴讹。","葛陂化龙之杖，陶家居蛰之梭。","同条生兮有数，同条死兮无多。","末后句，只这是，风舟载月浮秋水。"]},{"t":"颂古一百则 其八十一","f":"词","c":["夜壑藏舟，澄源著棹。","龙鱼未知水为命，折箸不妨聊一搅。","玄沙师，小塘老，函盖箭锋，探竿影草。","潜缩也老龟巢莲，游戏也华鳞弄藻。"]},{"t":"颂古一百则 其二十二","f":"词","c":["挫来机，总权柄。","事有必行之威，国有不犯之令。","宾尚奉而主骄，君忌谏而臣佞。","底意岩头问德山，一抬一搦看心行。"]},{"t":"颂古一百则 其三十一","f":"楚辞体","c":["一道神光，初不覆藏。","超见缘也是而无是，出情量也当而无当。","岩花之粉兮蜂房成蜜，野草之滋兮麝脐作香。","随类三尺一丈六，明明触处露堂堂。"]},{"t":"颂古一百则 其十二","f":"七言律诗","c":["宗说般般尽强为，流传耳口便支离。","种田博饭家常事，不是饱参人不知。","参饱明知无所求，子房终不贵封侯。","忘机归去同鱼鸟，濯足沧浪烟水秋。"]},{"t":"颂古一百则 其四","f":"词","c":["百草头上无边春，信手拈来用得亲。","丈六金身功德聚，等闲携手入红尘。","尘中能作主，化外自来宾。","触处生涯随分足，未嫌伎俩不如人。"]},{"t":"颂古一百则 其四十四","f":"楚辞体","c":["丝纶降，号令分，寰中天子，塞外将军。","不待雷惊出蛰，那知风遏行云。","机底联绵兮，自有金针玉线。","印前恢廓兮，元无鸟篆虫文。"]},{"t":"颂古一百则 其七十三","f":"词","c":["清白门庭四绝邻，长年关扫不容尘。","光明转处倾残月，爻象分时却建寅。","新满孝，便逢春，醉步狂歌任堕巾。","散发夷犹谁管系，太平无事酒颠人。"]},{"t":"颂古一百则 其五十六","f":"词","c":["抗力霜雪，平步云霄。","下惠黜国，相如过桥。","萧曹谋略能成汉，巢许身心欲避尧。","宠辱若惊深自信，真情参迹混渔樵。"]},{"t":"颂古一百则 其五十二","f":"词","c":["驴觑井，井觑驴。","智容无外，净涵有馀。","肘后谁分印，家中不蓄书。","机丝不挂梭头事，文彩纵横意自殊。"]},{"t":"颂古一百则 其四十七","f":"词","c":["岸眉横雪，河目含秋。","海口鼓浪，航舌驾流。","拨乱之手，太平之筹。","老赵州，老赵州，搅搅丛林卒未休。","徒费工夫也造车合辙，本无伎俩也塞壑填沟。"]},{"t":"颂古一百则 其二十五","f":"词","c":["扇子破，索犀牛，棬挛中字有来由。","谁知桂毂千年魄，妙作通明一点秋。"]},{"t":"颂古一百则 其六十六","f":"楚辞体","c":["规圆矩方，用行舍藏。","钝置栖芦之鸟，进退触藩之羊。","吃人家饭，卧自家床。","云腾致雨，露结为霜。","玉线相投透针鼻，锦丝不断吐梭肠。","石女机停兮夜色向午，木人路转兮月影移央。"]},{"t":"颂古一百则 其七十一","f":"词","c":["作贼心，过人胆，历历纵横对机感。","保福云门也垂鼻欺唇，翠岩长庆也脩眉映眼。","杜禅和，有何限，刚道意句一齐刬。","埋没自己也饮气吞声，带累先宗也面墙檐版。"]},{"t":"颂古一百则 其七十九","f":"词","c":["玉人梦破一声鸡，转盼生涯色色齐。","有信风雷催出蛰，无言桃李自成蹊。","及时节，力耕犁，谁怕春畴没胫泥。"]},{"t":"颂古一百则 其八十","f":"词","c":["蒲团禅版对龙牙，何事当机不作家。","未意成褫明目下，恐将流落在天涯。","虚空那挂剑，星汉却浮槎。","不萌草解藏香象，无底篮能著活蛇。","今日江湖何障碍，通方津渡有船车。"]},{"t":"颂古一百则 其二十四","f":"词","c":["玄沙太刚，长庆少勇，南山鳖鼻死无用。","风云际会头角生，果见韶阳下手弄。","下手弄，激电光中看变动。","在我也能遣能呼，于彼也有擒有纵。","底事如今付阿谁，冷口伤人不知痛。"]},{"t":"颂古一百则 其九","f":"楚辞体","c":["两堂云水尽分拿，王老师能验正邪。","利刀斩断具亡像，千古令人爱作家。","此道未丧，知音可嘉。","凿山透海兮唯尊大禹，鍊石补天兮独贤女娲。","赵州老，有生涯，草鞋头戴较些些。","异中来也还明鉴，只个真金不混沙。"]},{"t":"颂古一百则 其七十六","f":"楚辞体","c":["佛祖髑髅穿一串，宫漏沈沈密传箭。","人天机要发千钧，云阵煇煇急飞电。","个中人，看转变，遇贱则贵贵则贱。","得珠罔象兮至道绵绵，游刃亡牛兮赤心片片。"]},{"t":"颂古一百则 其九十九","f":"词","c":["不入世，未循缘，劫壶空处有家传。","白蘋风细秋江暮，古岸船归一带烟。"]},{"t":"颂古一百则 其四十八","f":"楚辞体","c":["曼殊问疾老毗耶，不二门开看作家。","珉表粹中谁赏鉴，忘前失后莫咨嗟。","区区抱璞兮楚庭膑士，璨璨报珠兮隋城断蛇。","休点破，绝疵瑕，俗气浑无却较些。"]},{"t":"颂古一百则 其九十六","f":"词","c":["石霜一宗，亲传九峰。","香烟脱去，正脉难通。","月巢鹤作千年梦，雪屋人迷一色功。","坐断十方犹点额，密移一步看飞龙。"]},{"t":"颂古一百则 其七十七","f":"楚辞体","c":["道环之虚靡盈，空印之字未形。","妙运天轮地轴，密罗武纬文经。","放开捏聚，独立周行。","机发玄枢兮青天激电，眼含紫光兮白日见星。"]},{"t":"颂古一百则 其六","f":"楚辞体","c":["药之作病，鉴乎前圣。","病之作医，必也其谁。","白头黑头兮克家之子，有句无句兮截流之机。","堂堂坐断舌头路，应笑毗耶老古锥。"]},{"t":"颂古一百则 其二","f":"词","c":["廓然无圣，来机径挺。","得非犯鼻而挥斤，失不回头而堕甑。","寥寥冷坐少林，默默全提正令。","秋清月转霜轮，河淡斗垂夜柄。","绳绳衣钵付儿孙，从此人天成药病。"]},{"t":"颂古一百则 其三十三","f":"词","c":["浪汲初升，云雷相送，腾跃棱棱看大用。","烧尾分明度禹门，华鳞未肯淹齑瓮。","老成人，不惊众，惯临大敌初无恐。","泛泛端如五两轻，堆堆何翅千钧重。","高名四海复谁同，介立八风吹不动。"]},{"t":"颂古一百则 其五十五","f":"词","c":["末后句，会也无，德山父子太含胡。","座中亦有江南客，莫向人前唱鹧鸪。"]},{"t":"颂古一百则 其四十","f":"词","c":["弦筈相衔，网珠相对。","发百中而箭箭不虚，摄众景而光光无碍。","得言句之总，持住游戏之三昧。","妙其间也宛转偏圆，必如是也纵横自在。"]},{"t":"颂古一百则 其五十九","f":"词","c":["三老暗转舵，孤舟夜回头。","芦花两岸雪，烟水一江秋。","风力扶帆行不棹，笛声唤月下沧洲。"]},{"t":"颂古一百则 其四十九","f":"楚辞体","c":["争解恁么道，五更鸡唱家林晓。","争肯恁么道，千年鹤与云松老。","宝鉴澄明验正偏，玉机转侧看兼到。","门风大振兮规步绵绵，父子变通兮声光浩浩。"]},{"t":"颂古一百则 其九十五","f":"词","c":["临际全机格调高，棒头有眼辨秋毫。","扫除狐兔家风峻，变化鱼龙雷火烧。","活人剑，杀人刀，倚天照雪利吹毛。","一等令行滋味别，十分痛处是谁遭。"]},{"t":"颂古一百则 其六十九","f":"词","c":["跛跛挈挈，㲯㲯毵毵。","百不可取，一无所堪。","默默自知田地稳，腾腾谁谓肚皮憨。","普周法界浑成饭，鼻孔累垂信饱参。"]},{"t":"颂古一百则 其十六","f":"词","c":["是与不是，好看棬。","似抑似扬，难兄难弟。","纵也彼既临时，夺也我何特地。","金锡一振太孤标，绳床三绕闲游戏。","丛林扰扰是非生，想像触髅前见鬼。"]},{"t":"颂古一百则 其四十三","f":"词","c":["斫断老葛藤，打破狐窠窟。","豹披雾而变文，龙乘雷而换骨。","咄，起灭纷纷是何物。"]},{"t":"颂古一百则 其三十","f":"词","c":["坏不坏，随他去也。","大千界句里了无钩锁机，脚头多被葛藤碍。","会不会分明，底事丁宁杀。","知心拈出勿商量，还我当行相买卖。"]},{"t":"颂古一百则 其八十四","f":"词","c":["俱胝老子指头禅，三十年来用不残。","信有道人方外术，了无俗物眼前看。","所得甚简，施设弥宽，大千刹海饮毛端。","鳞龙无限落谁手，珍重任公把钓竿。","师复竖起一指云，看。"]},{"t":"颂古一百则 其三","f":"词","c":["云犀玩月璨含辉，木马游春骏不羁。","眉底一双寒碧眼，看经那到透牛皮。","明白心超旷劫，英雄力破重围。","妙圆枢口转灵机，寒山忘却来时路，拾得相将携手归。"]},{"t":"颂古一百则 其三十八","f":"楚辞体","c":["迷悟相返，妙传而简。","春拆百花兮一吹，力回九牛兮一挽。","无奈泥沙拨不开，分明塞断甘泉眼。","忽然突出肆横流，险。"]},{"t":"颂古一百则 其八十五","f":"楚辞体","c":["孤迥迥，圆陀陀，眼力尽处高峨峨。","月落潭空夜色重，云收山瘦秋容多。","八封位正，五行气和，身先在里见来么。","南阳父子兮却似知有，西竺佛祖兮无如奈何。"]},{"t":"颂古一百则 其十八","f":"词","c":["狗子佛性有，狗子佛性无，直钩元求负命鱼。","逐气寻香云水客，嘈嘈杂杂作分疏。","平展演，大铺舒，莫怪侬家不慎初。","指点瑕疵还夺璧，秦王不识蔺相如。"]},{"t":"颂古一百则 其七十五","f":"词","c":["圆珠不穴，大璞不琢，道人所贵无棱角。","拈却肯路根尘空，脱体无依活卓卓。"]},{"t":"颂古一百则 其二十七","f":"词","c":["松直棘曲，鹤长凫短。","羲皇世人，俱忘治乱。","其安也潜鳞在渊，其逸也翔鸟脱绊。","无何祖祢西来，里许得失相半。","蓬随风而转空，船截流而到岸。","个中灵利衲僧，看取清凉手段。"]},{"t":"颂古一百则 其八十三","f":"词","c":["妙药何曾过口，神医莫能投手。","若存也渠本非无，至虚也渠本非有。","不灭而生，不亡而寿。","全超威音之前，独步劫空之后。","成平也天盖地擎，运转也乌飞兔走。"]},{"t":"颂古一百则 其三十二","f":"楚辞体","c":["无外而容，无碍而冲。","门墙岸岸，关锁重重。","酒常酣而卧客，饭虽饱而颓农。","突出虚空兮凤抟妙翅，踏翻沧海兮雷送游龙。"]},{"t":"颂古一百则 其七十四","f":"词","c":["没踪迹，断消息。","白云无根，清风何色。","散乾盖而非心，持坤舆而有力。","洞千古之渊源，造万像之模则。","刹尘道会也处处普贤，楼阁门开也头头弥勒。"]},{"t":"颂古一百则 其八","f":"词","c":["一尺水，一丈波，五百生前不奈何。","不落不昧商量也，依前撞入葛藤窠。","阿呵呵，会也么。","若是你洒洒落落，不妨我哆哆和和。","神歌社舞自成曲，拍手其间唱哩啰。"]},{"t":"颂古一百则 其十三","f":"词","c":["言衣半夜付卢能，搅搅黄梅七百僧。","临际一枝正法眼，瞎驴灭却得人憎。","心心相印，祖祖传灯。","夷平海岳，变化鲲鹏。","只个名言难比拟，大都手段解翻腾。"]},{"t":"颂古一百则 其九十四","f":"词","c":["卸却臭皮袋，拈转赤肉团。","当头鼻孔正，直下髑髅乾。","老医不见从来癖，少子相看向近难。","野水瘦时秋潦退，白云断处旧山寒。","须剿绝，莫颟顸。","转尽无功伊就位，孤标不与汝同盘。"]},{"t":"颂古一百则 其二十六","f":"楚辞体","c":["一倒一起，雪庭师子。","慎于犯而怀仁，勇于为而见义。","清光照眼似迷家，明白转身还堕位。","衲僧家，了无寄，同死同生，何此何彼。","暖信破梅兮春到寒枝，凉飙脱叶兮秋澄潦水。"]},{"t":"颂古一百则 其十七","f":"七言绝句","c":["秤头蝇坐便攲倾，万世权衡照不平。","斤两锱铢见端的，终归输我定盘星。"]},{"t":"颂古一百则 其一○一","f":"词","c":["见有不有，翻手覆手。","琅琊山里人，不落瞿昙后。"]},{"t":"颂古一百则 其九十","f":"词","c":["梦中拥衲参耆旧，列圣森森坐其右。","当仁不让犍稚鸣，说法无畏师子吼。","心安如海，胆量如斗。","鲛目泪流，蚌肠珠剖。","谵语谁知泄我机，厖眉应笑扬家丑。","离四句，绝百非，马师父子病休医。"]},{"t":"颂古一百则 其五十三","f":"词","c":["岐分丝染太唠唠，果缀花联败祖曹。","妙握司南造化柄，水云器具在甄陶。","屏割繁碎，剪除氄毛。","星衡藻鉴，玉尺金刀。","黄檗老，察秋毫，坐断春风不放高。"]},{"t":"颂古一百则 其五十四","f":"词","c":["一窍虚通，八面玲珑。","无象无私春入律，不留不碍月行空。","清净宝目功德臂，遍身何似通身是。","现前手眼显全机，大用纵横何讳忌。"]},{"t":"颂古一百则 其四十五","f":"词","c":["巍巍堂堂，磊磊落落。","闹处刺头，稳处下脚。","脚下线断我自由，鼻端泥尽君休斲。","莫动著，千年故纸中合药。"]},{"t":"颂古一百则 其九十七","f":"七言绝句","c":["君王底意语知音，天下倾诚葵藿心。","掇出中原无价宝，不同赵璧与燕金。"]},{"t":"颂古一百则 其四十六","f":"词","c":["收把断襟喉，风磨云拭，水冷天秋。","锦鳞莫谓无滋味，钓尽沧浪月一钩。"]},{"t":"颂古一百则 其十","f":"词","c":["年老成精不谬传，赵州古佛嗣南泉。","枯龟丧命因图象，良马追风累缠牵。","勘破了老婆禅，说向人前不直钱。"]},{"t":"颂古一百则 其二十三","f":"楚辞体","c":["淡中有味，妙超情谓。","绵绵若存兮象先，兀兀如愚兮道贵。","玉雕文以丧淳，珠在渊而自媚。","十分爽气兮清磨暑秋，一片闲云兮远分天水。"]},{"t":"颂古一百则 其二十九","f":"词","c":["铁牛之机，印住印破。","透出毗卢顶?行，却来化佛舌头坐。","风穴当衡，卢陂负堕。","棒头喝下，电光石火。","历历分明珠在盘，眨起眉毛还蹉过。"]},{"t":"颂古一百则 其十九","f":"词","c":["不起一念须弥山，韶阳法施意非悭。","肯来两手相分付，拟去千寻不可攀。","沧海阔，白云闲，莫将毫发著其间。","假鸡声韵难谩我，未肯模胡放过关。"]},{"t":"颂古一百则 其七十","f":"词","c":["豁落亡依，高闲不羁，家邦平贴到人稀。","些些力量分阶级，荡荡身心绝是非。","是非绝，介立大方无轨辙。"]},{"t":"颂古一百则 其八十九","f":"词","c":["草漫漫，门里门外君自看。","荆棘林中下脚易，夜明帘外转身难。","看看，几何般。","且随老木同寒瘠，将逐春风入烧瘢。"]},{"t":"颂古一百则 其一○○","f":"楚辞体","c":["钵里饭，桶里水，开口见胆求知己。","拟思便落二三机，对面忽成千万里。","韶阳师，较些子。","断金之义兮谁与相同，匪石之心兮独能如此。"]},{"t":"颂古一百则 其三十五","f":"楚辞体","c":["摇头摆尾赤梢鳞，彻底无依解转身。","截断舌头饶有术，拽回鼻孔妙通神。","夜明帘外兮风月如昼，枯木岩前兮花卉长春。","无舌人，无舌人，正令全提一句亲。","独步环中明了了，任从天下乐欣欣。"]},{"t":"颂古一百则 其五十八","f":"词","c":["缀缀功过，胶胶因果。","镜外狂奔演若多，杖头击著破灶堕。","灶堕破，来相贺，却道从前辜负我。"]},{"t":"颂古一百则 其三十六","f":"词","c":["日面月面，星流电卷。","镜对像而无私，珠在盘而自转。","君不见钳锤前百鍊之金，刀尺下一机之绢。"]},{"t":"颂古一百则 其九十三","f":"词","c":["别是非，明得丧。","应之心，指诸掌。","往来不往来，只者俱是藏。","轮王赏之有功，黄帝得之罔象。","转枢机，能伎俩，明眼衲僧无卤莽。"]},{"t":"颂古一百则 其八十六","f":"词","c":["九包之雏，千里之驹。","真风度籥，灵机发枢。","劈面来时飞电急，迷云破处太阳孤。","捋虎须，见也无，个是雄雄大丈夫。"]},{"t":"颂古一百则 其六十四","f":"词","c":["离念见佛，破尘出经。","现成家法，谁立门庭。","月逐舟行江练净，春随草上烧痕青。","拨不拨，听丁宁，三径就荒归便得，旧时松菊尚芳馨。"]},{"t":"颂古一百则 其十四","f":"楚辞体","c":["觌面来时作者知，可中石火电光迟。","输机谋主有深意，欺敌兵家无远思。","发必中，更谩谁。","脑后见腮兮人难触犯，眉底著眼兮渠得便宜。"]},{"t":"颂古二十一首 其二十二","f":"词","c":["智门真得祖家风，放出云门广长舌。","大智如愚，大巧若拙，用尽工夫参不彻。","莫于平地上增堆，休向虚空里钉橛。"]},{"t":"颂古二十一首 其二十一","f":"词","c":["大众退后，衲僧去就。","岂用机关，那容体究。","蓑翁老熟惯风波，桡棹不施船放溜。"]},{"t":"颂古二十一首 其二十","f":"词","c":["翡翠帘垂，丝纶未济。","紫罗帐合，视听难通。","犯动毛头，月升夜扃。","密移一步，鹤出银笼。","脱身一色无遗影，不坐同风落大功。"]},{"t":"颂古二十一首 其十九","f":"七言律诗","c":["雪老大开方便路，低头却入庵中去。","者僧有眼恰如盲，却被岩头行一步。","者僧好休不肯休，依然依路去悠悠。","元来不会雪峰意，却被岩头瓮赣头。"]},{"t":"颂古二十一首 其十七","f":"五言绝句","c":["无人接得渠，遗逼马相如。","果来桥上也，记得柱头书。"]},{"t":"颂古二十一首 其十五","f":"词","c":["即日贵人，旧家贫汉。","兄弟相承，尊卑互换。","向晚途中眼不开，夜明帘外机旋转。","骑牛戴帽异中来，百鍊真金色不变。"]},{"t":"偈颂二百零五首 其七十六","f":"词","c":["渠非老朽，不礼不受。","威音世前，毗卢顶后。","把定壶中白日长，触著匣内青蛇吼。","良医叮嘱病人，服药不如忌口。"]},{"t":"颂古二十一首 其十三","f":"七言律诗","c":["双盲入暗路崎岖，日落栖芦暂得苏。","争似石人眠半夜，免教舜让守林居。","须知花绽非干木，无脚行时早触途。","昨朝风起长安道，元是昆崙进国图。"]},{"t":"颂古二十一首 其七","f":"词","c":["青山不异，白玉无瑕。","茫茫流水，扰扰黄花。","有佛处纤毫不立，无佛处万别千差。","长安路上未归客，寻溪由自摘杨花。"]},{"t":"颂古二十一首 其四","f":"五言绝句","c":["沩山水牯牛，禅人聚头咬。","可怜负舂人，唤作岭南獠。"]},{"t":"颂古二十一首 其三","f":"七言绝句","c":["我这镰子用得快，当时三十文钱买。","南泉门下路歧通，寄语行人著精彩。"]},{"t":"假日山行","f":"七言律诗","c":["平生胸中云外峰，有閒便与扶瘦筇。","但知一世丘壑味，想得十分猿鸟从。","明见秋容山洗雨，清可人意风吟松。","归来游兴散不尽，谁杵唤月黄昏钟。"]},{"t":"偈十首 其十","f":"词","c":["衲僧巴鼻，圆明绝颣。","直须推倒，却要扶起。","玉马饮乾明月泉，泥牛耕破玻璃地。","披毛戴角异中来，天上人间能几几。"]},{"t":"偈十首 其八","f":"五言律诗","c":["触目绝对待，万法无不在。","是汝心不知，非汝心不会。","不会无不会，不知无不知。","只个不会知，殊特也大奇。"]},{"t":"偈十首 其六","f":"七言绝句","c":["万像之中独露身，唯人自肯乃方亲。","昔年谬向途中觅，今日观来火里冰。"]},{"t":"偈十首 其五","f":"五言绝句","c":["牢笼不肯住，呼唤不回头。","古圣不安排，至今无处所。"]},{"t":"偈十首 其四","f":"词","c":["心是根，法是尘，两种犹如镜上痕。","尘垢尽时光始现，心法双忘性即真。"]},{"t":"偈十首 其三","f":"词","c":["男子身中入正定，女子身中从定起。","一尘入正受，诸尘三昧起。","展翅奔腾六合云，抟风鼓荡四溟水。"]},{"t":"偈十首 其二","f":"词","c":["万法是心光，诸缘唯性晓。","本无迷悟人，只要今日了。","心无形影，对缘即照。"]},{"t":"偈颂七十八首 其三","f":"词","c":["山云冉冉，江水茫茫。","正不居位，偏不涉傍。","显而不露，隐而弥彰。","猿啼古木音声急，鹤宿枯松梦寐长。"]},{"t":"偈颂七十八首 其六十九","f":"词","c":["云无心而自闲，天无际而能宽。","道无像而普应，神无虑而常安。","随之也不见去吊，迎之也不见来端。","一藏教祇成赞叹，三世佛止可傍观。","烛晓堂虚，织妇转机梭路细。","水明夜静，渔老拥蓑船月寒。"]},{"t":"偈颂七十八首 其四十二","f":"七言绝句","c":["声色见闻闹浩浩，怡似儿时斗百草。","两家拈出一般般，相对无言点头笑。"]},{"t":"偈颂七十八首 其二十二","f":"词","c":["性觉妙明，本觉明妙。","与太虚等量，与物情同道。","应色应声，随听随眺。","入三世而非去来，混万缘而无正倒。","云日低时字雁横，夜蟾落处孤猿叫。"]},{"t":"偈颂七十八首 其五十三","f":"楚辞体","c":["道绵绵兮用也不勤，道绵绵兮寂也不灭。","二乘困堕于空无，众生执迷于分别。","菩萨区区于进修，诸佛唠唠于演说。","一句子妙出三乘，一念閒功超万劫。","水月茫茫兮舟棹闲，雪云冉冉兮路岐绝。","明明灵灵兮唯己自知，大辩若讷兮大巧若拙。"]},{"t":"偈颂七十八首 其七十八","f":"七言律诗","c":["地水火风休假藉，一切不留还脱洒。","家风廓落等虚空，田地虚明非昼夜。","鸟道须知举足难，玄机不许丝头挂。","同中有异异中同，彻底浑沦无缝罅。"]},{"t":"偈颂七十八首 其七十四","f":"七言律诗","c":["生灭心尽是寂灭，露柱怀胎底时节。","寂灭心起是生灭，石女生儿解言说。","用时万象不盈馀，休处一真无空缺。","藤枯树倒笑呵呵，依旧清风与明月。"]},{"t":"偈颂七十八首 其二十七","f":"七言古诗","c":["藏身须要无踪迹，碧眼胡僧难辨白。","没踪迹处莫藏身，门门廓达了诸尘。","独来将谓无俦侣，闹里忽然逢故人。","柳线含金犹畏冷，梅花破雪已成春。","阿侬千眼通身是，善应无方处处真。"]},{"t":"偈颂七十八首 其十五","f":"五言绝句","c":["青山白云父，白云青山儿。","白云终日倚，青山总不知。"]},{"t":"偈颂七十八首 其三十一","f":"词","c":["一雨一晴，底事分明。","六尘昏扰，世界峥嵘。","一心虚泊，万法齐平。","出得气是你鼻孔，觑得破是你眼睛。","有缘不是余朋友，无用双眉却弟兄。"]},{"t":"偈颂七十八首 其四十五","f":"词","c":["五月半，农忙乱，插田心是秋成饭。","却道禾熟不临场，祇么任从风雨烂。","禅和子，一身了。","一身两眼对两眼，个中丝发初无间。","老狐涎尽复何疑，再坐盘中弓落盏。"]},{"t":"偈颂七十八首 其五十一","f":"七言绝句","c":["南亩黄云禾弄穟，中洲白雪苇成花。","归舟恰向其閒过，一棹清风夜到家。"]},{"t":"偈颂七十八首 其五十六","f":"五言绝句","c":["直下无窠窟，不用求奇特。","皓玉本无瑕，雕文丧君德。"]},{"t":"偈颂七十八首 其九","f":"词","c":["心不自心始是心，眼不见眼始是眼。","堂堂无影迹，历历绝思惟。","明满环中，兔怀夜月。","翠横海上，犀晕秋山。","直须及尽玄微，始解承当底事。"]},{"t":"偈颂七十八首 其六十二","f":"词","c":["一二三四五，禾山打鼓金牛舞。","劈面来时著眼看，全身放下休回互。"]},{"t":"偈颂七十八首 其七十六","f":"词","c":["赵州四门长开，不碍诸方往来。","十字街头人大叫，平铺买卖没相猜。"]},{"t":"偈颂七十八首 其六十六","f":"七言绝句","c":["一尘具无量刹土，一念超无量劫数。","一身现无量众生，一体合无量诸佛。"]},{"t":"偈颂七十八首 其四十三","f":"七言绝句","c":["碧琉璃色水澄清，紫磨金光身瑩明。","洗净方知不受垢，释迦老子此时生。"]},{"t":"偈颂七十八首 其六十三","f":"词","c":["活计如今付旧人，版头疏久又还亲。","星河月与长江混，渺渺清光一色匀。","底时节，落功勋。","卧稳须知却转身，转得了来相识么，寒穷面觜黑皴皴。"]},{"t":"偈颂七十八首 其八","f":"词","c":["丙丁童子来求火，南海波斯鼻孔大。","狤獠舌头会者难，直下而今照得破。","照得破，没功过。","知你被底穿，曾与同床卧。","廉纤脱尽旧时疑，杯影蛇弦留再坐。"]},{"t":"偈颂七十八首","f":"词","c":["黄蘖传来，临际用底，定上座触著关捩。","廓然一念忘缘，泊尔十方无寄。","现前不用安排，直下何劳拟议。","不风流处也风流，有意气时添意气。"]},{"t":"偈颂七十八首 其六十","f":"词","c":["同中有异，功亡就位。","异中有同，在位借功。","一步密移玄路转，全身放下劫壶空。","隐隐密密，玲玲珑珑。","记取深云须变豹，自然死水不藏龙。"]},{"t":"偈颂七十八首 其三十二","f":"词","c":["即日贵人，旧家富汉。","兄弟相成，尊宾互换。","突晓途中眼不开，夜明帘外机旋转。","骑牛戴帽异中来，百炼真金色不变。"]},{"t":"偈颂七十八首 其五","f":"五言古诗","c":["十五日已前，有口说不得。","十五日已后，无心却自然。","正当十五日，云笼无缝袄，花笑不萌枝。"]},{"t":"偈颂七十八首 其十九","f":"词","c":["寥寥无异辙，密密去玄功。","月转芦花岸，水秋吞太空。","欲识诞生王子父，鹤腾霄汉出银笼。"]},{"t":"偈颂七十八首 其十六","f":"词","c":["当生不生，借光现三十六应。","当灭不灭，忘照摄千百亿身。","祇如绝去，来无动静。"]},{"t":"偈颂七十八首","f":"五言绝句","c":["明明百草头，明明祖师意。","于佗未尝一，于我未赏异。"]},{"t":"偈颂七十八首 其七十五","f":"词","c":["不是男，不是女。","不是神，不是鬼。","不是佛，不是物。","祇知白云无心，谁辨青山在目。","夜明识取断蛇珠，潭寒退下苍龙骨。","等闲掣断紫丝绦，天上人间收不得。","收不得，底事从来没窠窟。"]},{"t":"偈颂七十八首 其三十三","f":"词","c":["心月孤圆，义天洞晓。","照中之虚，虚中之照。","不萌枝上鸟初惺，无影树头春不老。","垢衣权挂类中来，出门信手拈来草。"]},{"t":"偈颂七十八首 其五十七","f":"七言古诗","c":["本来田地无涯岸，极目寒光成一片。","消息平沈佛也迷，机轮转侧谁能辨。","雪山山下拥蓑人，白牛一掣芒绳断。"]},{"t":"偈颂七十八首 其四十九","f":"词","c":["日照昼，月照夜。","天清而高，地厚而下。","不我处者大功，不可逃者至化。","举起镇州罗卜，酬却庐陵米价。","阿噜勒继萨婆诃，佳作人可知礼也。"]},{"t":"偈颂七十八首 其六十五","f":"词","c":["何须更举扬，全体露堂堂。","湿暑时时雨，薰风阵阵香。","秧针初透水痕浅，蒲刀欲剪柳丝长。","双六盘中休喝彩，分明触事恰相当。"]},{"t":"偈颂七十八首 其一","f":"七言绝句","c":["易外家风未兆时，三更黑马上乌鸡。","而今拨转机轮也，刹刹尘尘更是谁。"]},{"t":"偈颂七十八首 其五十八","f":"词","c":["灵苗发种，觉树敷春。","冷湫湫处却要温和，乾爆爆时还须津润。"]},{"t":"偈颂七十八首 其六十四","f":"五言绝句","c":["万物自有功，当言用极处。","事存函盖合，理应箭锋柱。"]},{"t":"偈颂七十八首 其十","f":"词","c":["一不是，二不成。","介然独立，法尔双行。","柳线渐摇风力嫩，草针齐上烧痕青。","一点灵光普天地，更嫌何处不分明。","閒里摸著鼻孔，忙时换却眼睛。"]},{"t":"偈颂七十八首 其四十一","f":"词","c":["五九四十五，春风吹断前山雨。","行云归去复何心，转背飘然无觅处。","无觅处，知不知，坐断十方还是谁。","东弗于代郁单越，西瞿耶尼阎浮提。"]},{"t":"偈颂七十八首 其十二","f":"词","c":["习习春风，丝丝春雨。","一等沾濡，十方周普。","甘草得之甜，黄连得之苦。","天意发丛林，檐声闹窗户。","古德尝云己不迷，等闲教坏人男女。"]},{"t":"偈颂七十八首 其三十九","f":"词","c":["内若不动，外必不乱，个是丛林知有汉。","而今识得不为冤，自家兵马何须战。","心因不生境缘断，体若虚空勿崖岸。","霜天皎月上中峰，一段光明洗痴暗。"]},{"t":"偈颂七十八首 其七十九","f":"词","c":["赵州道有，赵州道无。","狗子佛性，天下分疏。","面赤不如语直，心真莫怪言粗。","七百甲子老禅伯，驴粪逢人换眼珠。"]},{"t":"偈颂七十八首 其六十一","f":"词","c":["麟龙不为瑞，珠璧不为贵。","衲僧眼豁开，彻见生死蒂。","生死蒂，第一义。","诸佛心，祖师鼻。","少林传灯，灵山授记。","随高随下，何此何彼。","假诸因缘，神通游戏。","有时五教三乘，有时三德六味。","有时屋里主财，有时门头了事。","处处清白家风，人人见成活计。"]},{"t":"偈颂七十八首 其二十","f":"词","c":["百骸俱溃散，一物镇长灵。","白云功尽青山秀，青山路转白云迎。","不曾死，不曾生。","金绳拽转泥牛鼻，半夜驱来海上耕。"]},{"t":"偈颂七十八首 其十四","f":"词","c":["心不能缘，口不能议。","直须退步荷担，切忌当头触讳。","风月寒清古渡头，夜船拨转琉璃地。"]},{"t":"偈颂七十八首 其二十五","f":"词","c":["佛病法病，佛药法药。","本色衲僧，俱不染著。","遇饭开口，要行移脚。","自是现成，谁能造作。","言满天下无口过，行满天下无怨恶。"]},{"t":"偈颂七十八首 其二","f":"词","c":["同声相应，同气相求。","同风千里，不隔丝头。","脱尽情尘消息在，芦花江上月明秋。"]},{"t":"偈颂七十八首 其五十四","f":"词","c":["恰恰无绫缝，明明不覆藏。","鹫岭岂传迦叶，少林那付神光。","现成处处合头句，具足人人知见香。","虚空说法森罗听，不挂唇皮解举扬。"]},{"t":"偈颂七十八首 其二十一","f":"五言绝句","c":["一言尽十方，万卷该不得。","一步周八弦，驷马追不及。"]},{"t":"偈颂七十八首 其二十三","f":"七言绝句","c":["云在青天水在瓶，几人错认定盘星。","药山八字轰开也，恰到而今话大行。"]},{"t":"偈颂七十八首 其四十七","f":"词","c":["祇解恁么去，沙禽夜宿沧洲树。","不解恁么来，石笋穿开古路苔。","莫道鲲鲸无羽翼，今日亲从鸟道回。"]},{"t":"偈颂七十八首 其三十四","f":"词","c":["掣鼓夺旗，往往光影里走作。","停机息杼，往往死水里浸却。","衲僧家，稳下脚。","没窠臼，莫栖泊。","月树不啼猿，云巢无宿鹤。","玄微及尽类难齐，千手大悲难摸索。"]},{"t":"偈颂七十八首 其六十八","f":"词","c":["寒岩异草，坐著成功。","明月白云，步时分影。","幽洞不拘关锁意，纵横那涉两头人。"]},{"t":"偈颂七十八首 其七十","f":"词","c":["芝麻压得油，粳米炊得饭，还我丛林饱参汉。","衲僧履道贵平怀，何必临机争转换。","活计自然，家风成现。","顺水便风，归舟到岸。","寒山拾得笑呵呵，此心分付知音辨。"]},{"t":"偈颂七十八首 其三十六","f":"词","c":["云从龙，风从虎。","雪峰辊毬，禾山打鼓。","意不立玄，机不停午。","恰恰相当用不穷，道吾觑破乐神舞。"]},{"t":"偈颂二百零五首 其一八六","f":"词","c":["地藏栽田做活计，南泉镰子能收刈。","日用平怀稳便休，自然颗糁无遗弃。","无遗弃，不容易。","你也莫亏我，我也不亏你。","两家宾主平，四棱齐塌地。","风不鸣条，雨不破块，个是丛林饱参底。","牧来纯熟水牯牛，检点将来堕随类。"]},{"t":"偈颂二百零五首 其一五七","f":"词","c":["尘尘三昧，彼彼不外。","千峰向岳，百川赴海。","更无一法不如来，只个堂堂观自在。"]},{"t":"偈颂二百零五首 其一四五","f":"七言绝句","c":["吸尽西江向汝道，马师家风不草草。","截流一棹破烟寒，天水同秋清渺渺。"]},{"t":"偈颂二百零五首 其一○七","f":"词","c":["不起一念，向道须弥。","舌头一脔肉，口唇两边皮。","云门得用妙如许，不落是非知不知。"]},{"t":"偈颂二百零五首 其二十一","f":"词","c":["深明无底，灵异无根。","案山行尽，不见有家。","识浪沥乾，不见有己。","石女掣开金锁钥，木人拨动玉轮机。","方信道从佛口生，法化生得佛法分。"]},{"t":"偈颂二百零五首 其一二二","f":"词","c":["十月朔，风雨肇寒天意作。","丛席地炉今日开，免烧木佛无斟酌。","丹霞将错就错，院主眉须堕落。","如聋如盲大家翁，搅扰杀你不要恶。"]},{"t":"偈颂二百零五首 其三十","f":"词","c":["只个家风，八面玲珑。","斗柄横而河淡，梦鹤起而巢空。","功中退步就位，位里移身借功。","灵灵了了处同中有异，湛湛澄澄处异中有同。","随宜也机轮宛转，妙应也关捩虚通。","佛子住此地，即是佛受用。","经行及坐卧，常在于其中。"]},{"t":"偈颂二百零五首 其一五六","f":"楚辞体","c":["来问此经低声，大千卷自尘中出，三世佛从口里生。","天得一以清，地得一以宁，空无依兮谷不盈。","摩诃般若波罗密，落日渔樵歌太平。"]},{"t":"偈颂二百零五首 其七十四","f":"词","c":["长者长法身，短者短法身。","虚空已是色，大地却非尘。","觑得破阿那律祖，放得稳舜若多神。","飘飘闲戏白鸥水，栩栩梦游蝴蝶春。","拶头拶面推来也，眼里无筋一世贫。"]},{"t":"偈颂二百零五首 其一三五","f":"词","c":["一阳生，万物潜萌。","隐隐有像，寥寥未形。","蚌肠含妙蕴，犀角晕通星。","密密用，细细行，本智虚融与理冥。","露地白牛肥腻饱，拥蓑人驾雪山耕。"]},{"t":"偈颂二百零五首 其六十八","f":"词","c":["不可得一，不可得异，我如是也彼如是。","两茎眉现燄光身，百草头扬祖师意。","归云谁使就青山，落华自得随流水。"]},{"t":"偈颂二百零五首 其八十五","f":"楚辞体","c":["一句超然，良马影鞭。","道出语默，理合方圆。","运斤之妙，宾主可怜。","斲轮之伎，父子不传。","莫将爻象兮相求龟壳，才落是非兮底事驴年。"]},{"t":"偈颂二百零五首 其二○五","f":"词","c":["一雨沾濡，诸根萌动。","青黄各成其姿，长短各随其用。","绵绵也妙有机丝，混混也廓无棱缝。","若人问我如何，敢道不快漆桶。"]},{"t":"偈颂二百零五首 其三","f":"五言古诗","c":["恁么去底错，恁么去底亲。","错时错到底，亲时亲见真。","相识满天下，知心能几人。"]},{"t":"偈颂二百零五首 其一九六","f":"词","c":["若恁么，也难得，清光浩荡无瑕隙。","人言千里本同风，我道十方浑一色。","浑一色，须转侧。","才转侧，透关隔。","透关隔，酬尔平生今脱白。","侬家龟鹤自成仙，昨夜龙门无宿客。"]},{"t":"偈颂二百零五首 其一二六","f":"词","c":["王老师，足意气，是是非非荡情谓。","倚天照雪烂光芒，扫尽搀抢千万里。"]},{"t":"偈颂二百零五首 其七十三","f":"词","c":["渊默之津，皓然之色。","混处功齐，细看转侧。","昆仑脱手黄金绳，鼻孔累垂收不得。"]},{"t":"偈颂二百零五首 其一五五","f":"词","c":["寻常撞搕，当面讳却。","可怜傅大师，处处失楼阁。"]},{"t":"偈颂二百零五首 其一三二","f":"词","c":["不即不离，非取非舍。","自东自西，谁上谁下。","委曲也顺俗亡功，蓦直也应真不借。","珠中有火君须信，休向天边问太阳。"]},{"t":"偈颂二百零五首 其一一四","f":"词","c":["归根得旨，叶落知秋。","拈得鼻孔，失却舌头。","照彻三世佛之顶?，把定历代祖之襟喉。","玉井涵碧，冰壶断流。","诸法空寂为之座，是须坐处不停囚。"]},{"t":"偈颂二百零五首 其七十","f":"词","c":["三界唯心，唯心三界，一切法空观自在。","处处光明处处身，者回泡幻同无碍。","吐云如山，吞川如海，了无毛发居其外。","万象森罗尽我家，只个虚空肚皮大。"]},{"t":"偈颂二百零五首 其一八九","f":"词","c":["九月又重阳，菊华依旧黄。","渊明是醉不是酒，荡荡游心于大方。"]},{"t":"偈颂二百零五首 其一四六","f":"七言绝句","c":["白云之宾青山伴，位里借功看互换。","无底合盘转手擎，穿心碗子通身饭。"]},{"t":"偈颂二百零五首 其二十","f":"词","c":["舌头一脔肉，口唇两片皮。","其间无固必，分外莫猜疑。","赵州古佛，云门圣师，历历机头不挂丝。","自然桃李成蹊去，那是春风作意吹。"]},{"t":"偈颂二百零五首 其一○五","f":"楚辞体","c":["寿等南山，位崇北斗。","机运象先，体同道久。","明逾日月兮普及幽深，德合乾坤兮廓无前后。"]},{"t":"偈颂二百零五首 其五十七","f":"词","c":["无事题取一首，我侬不落他人后。","略略绰绰思大口，醇醇酽酽白家酒。","醉中犹道未沾唇，被人问著还打手。","不打手，三年一闰，冬后数九。"]},{"t":"偈颂二百零五首 其一二三","f":"词","c":["深深处，细细行。","隐隐时，密密觑。","若能恁么彻根彻，源旁参回互宛转。","虚玄不触尊贵机，横梭度针露线穿。"]},{"t":"偈颂二百零五首 其一一五","f":"词","c":["当处出生，当处灭尽。","三世如来，相授此印。","石人放意卧烟寒，玉女摇头看晓信。"]},{"t":"偈颂二百零五首 其九十九","f":"楚辞体","c":["饮乾巨海，推倒须弥，廓大灵通更是谁。","馨香秀林栴檀枝，哮吼出屈师子儿。","三千界现一弹指，八万门开双用眉。","知不知，为不为。","道满十处兮心超亿劫，影流万象兮气分二仪。"]},{"t":"偈颂二百零五首 其一六七","f":"词","c":["静沉沉，明荡荡，雪满十方，云迷四向。","一色影里是谁坐著功勋，百尺竿头阿你变通伎俩。","恁么时须辨几微，恁么处须明的当。","趁不去露地白牛，透得过流河香象。","彻见其源，如指诸掌。","恁么尽去也无法可传，恁么却来也有人相亮。"]},{"t":"偈颂二百零五首 其八十三","f":"词","c":["正昼热，深夜凉，冰壶谁复到中央。","身心直许摩云月，脾肺都将洗雪霜。","莫守一色处，莫坐万年床。","玉人转侧机梭动，细辨里头偏正方。"]},{"t":"偈颂二百零五首 其四十六","f":"词","c":["去也五年，分疏不下，一句元无缝罅。","只知推过商量，谁信分明酬价。","玲珑底相知，莽卤底相讶。","宁可与晓事人相骂，不可共不晓事人说话。"]},{"t":"偈颂二百零五首 其一五二","f":"词","c":["笊篱木杓，钱贯井索。","受用见成，家风廓落。","生涯放得信缘看，佛法更于何处著。","不用安排只么从，自然心地常安乐。"]},{"t":"偈颂二百零五首 其七十一","f":"七言古诗","c":["佛身光明了无垢，性水清净常不浑。","降生沐浴吉祥事，要以大开功德门。","哆哆和和增口业，胶胶缀缀添尘结。","大家净洗佛浑身，彻底洞然明皎洁。","长时诸佛洗我身，今日众僧洗我佛。"]},{"t":"偈颂二百零五首 其一七○","f":"词","c":["三寸舌，两片唇，无始时来赚杀人。","解弄不教圭角露，阿谁参见跛云门。"]},{"t":"偈颂二百零五首 其八十四","f":"词","c":["身里出门，门里出身。","白云能作客，明月解随人。"]},{"t":"偈颂二百零五首 其一六八","f":"楚辞体","c":["三世诸佛不知有，忉忉怛怛扬家丑。","狸奴白牯却知有，跛跛挈挈能自守。","弄鳖鼻兮忆南山，透法身兮藏北斗。","风飘白雪岭头梅，春撚金丝堤上柳。","天童也要不沾唇，三盏清源白家酒。"]},{"t":"偈颂二百零五首 其七十二","f":"词","c":["时行即行卓然何倚，时止即止廓尔独灵。","历万变而不我求功，住一如而不我藏用。"]},{"t":"偈颂二百零五首 其八十一","f":"词","c":["踏破草鞋赤脚走，拄杖头上挑日月。","智门真得祖家风，放出云门广长舌。","大智如愚，大功若拙，用尽工夫参不彻。","莫于平地上增堆，休向虚空里钉橛。"]},{"t":"偈颂二百零五首 其一四四","f":"七言绝句","c":["桃华浪里振脩鳞，一跃龙门看化身。","谛了十方三世事，无始的的自家春。"]},{"t":"偈颂二百零五首 其五十","f":"词","c":["唯只一真心，三缘坐断谁升沉。","遂成十法界，六道轮回自障碍。","不见一法即如来，方得名为观自在。","见怪不怪，其怪自坏。","灵从何来，圣亦何在。","拄杖敲时灶堕摧，一片虚明绝中外。"]},{"t":"偈颂二百零五首 其五十六","f":"词","c":["钓尽沧波月一钩，月低烟树夜维舟。","寒鸡抖擞呼天晓，笑对春风百草柔。","中外夷犹，纵横自由。","志公不是閒和尚，刀尺相将拄杖头。"]},{"t":"偈颂二百零五首 其八十八","f":"词","c":["不展事，不投机。","不徇缘，不答话。","个是出格，辙脱窠臼。","平生肝胆向人倾，相识犹如不相识。"]},{"t":"偈颂二百零五首 其一一六","f":"词","c":["雪峰之子，德山之孙，葛藤牵转难穷根。","截断众流见源底，相应函盖同乾坤。","长长短短无节奏，绵绵密密忒鹘仑。","随波逐浪恁么去，上船便到家前门。"]},{"t":"偈颂二百零五首 其七十七","f":"楚辞体","c":["不是心，不是物。","非天非人，非僧非俗。","南北东西莫我寻，长短方圆莫我测。","牛饮星河，兔眠月窟，彻底灵明破昏塞。","末山超拔兮顶相不形，铁磨变通兮舌头无骨。"]},{"t":"偈颂二百零五首 其一一八","f":"词","c":["冰鉴净，玉壶寒。","一亘清处抬脚易，十分明白转身难。","混身转却舌头短，转却浑身鼻孔宽。"]},{"t":"偈颂二百零五首 其二","f":"七言绝句","c":["妙存湛湛不为无，真照灵灵不为有。","更向其间退步看，白云断处青山瘦。"]},{"t":"偈颂二百零五首 其八十七","f":"词","c":["父母所生眼，悉见三千界，拈却案山谁我碍。","直饶全象无全牛，未免依前还碍塞。","衲僧家，真庆快。","物我虚空，混成一块。","更于何处著根尘，祇个堂堂观自在。"]},{"t":"偈颂二百零五首 其七","f":"七言绝句","c":["吸尽西江向汝道，马师不肯落荒草。","三千刹海一成秋，明月珊瑚冷相照。"]},{"t":"偈颂二百零五首 其六十一","f":"七言绝句","c":["灵云却解见桃华，老眼如今冷淡些。","拈却面前案山子，柱门路直不横斜。"]},{"t":"偈颂二百零五首 其一七八","f":"楚辞体","c":["吃粥了，洗钵去，法尔圆成正规矩。","可怜叶氏怕真龙，却怪谢郎欺猛虎。","本常路，真实语，这僧且问如何悟。","从来鼻孔大头垂，不用安排兮自著处所。"]},{"t":"偈颂二百零五首 其二十四","f":"词","c":["巢知风，穴知雨。","不用安排，自成规矩。","历历靡缘，閒閒何偶。","乐哉林鸟渊鱼，一笑相忘尔汝。"]},{"t":"偈颂二百零五首 其二○二","f":"词","c":["演出一大藏，明明超过诸缘上。","随曲随直也流水转山，随高随下也虚舟驾浪。"]},{"t":"偈颂二百零五首 其一九二","f":"词","c":["释迦自是释迦，然灯莫要添些。","不用烧钱引鬼，何须勾贼破家。","你那里针劄不入，我这里石上栽华。"]},{"t":"偈颂二百零五首 其一○○","f":"词","c":["宿雨洗去山面尘，东君料理山家春。","浩劫壶中勿新岁，枯木岩前有古人。","寒暑不到以法界为处，齿发不老以虚空为身。","坐间默有相传意，川上乾无逝去津。"]},{"t":"偈颂二百零五首 其九十三","f":"词","c":["几许欢心几许愁，好看野老两眉头。","家风平贴清如镜，水瘦山空一样秋。","手段通变，身心自由，不怕风涛雪拥舟。","海上三山颓一掣，六鳌连落上金钩。","华岳连天秀，黄河辊底流。"]},{"t":"偈颂二百零五首 其三十四","f":"词","c":["不居功，不合伴，脱体其间过一遍。","梦觉船浮明月波，眼寒雪拥芦华岸。"]},{"t":"偈颂二百零五首 其四十一","f":"楚辞体","c":["爱结成身，想澄成界，从此漂流生死海。","照彻灵源湛不浑，方知幻泡同无碍。","六门气秋，四大缘坏，了了一真常自在。","明月混融兮雪芦眼迷，清风相送兮夜船归快。"]},{"t":"偈颂二百零五首 其一四三","f":"词","c":["世梦短，劫壶宽，底人退步里头看。","豹变文而雾重，龙不卧而潭寒。","欲使人人双眼冷，要须先沥髑髅乾。"]},{"t":"偈颂二百零五首 其九十二","f":"楚辞体","c":["灵机未动，道环先入。","极理也妙得穷通，顺事也聊分借借。","无象无私，何固何必。","娟娟印水之月魂，冉冉在华之春律。","巍巍堂堂兮炜炜煌煌，三千大千兮周行独立。"]},{"t":"偈颂二百零五首 其一一三","f":"词","c":["世尊无说说，迦叶不闻闻。","默默到时良自庆，家山元在白云根。"]},{"t":"偈颂二百零五首 其一三一","f":"楚辞体","c":["道契如如，非有非无。","静也神之在谷，应也像之在珠。","了无所住，照不失虚，无影杖子两人扶。","清华临于至鉴，深密守于元枢，机轮文彩妙穷初。","霁色廓澄兮秋怀月满，秀棱重叠兮云卷山癯。"]},{"t":"偈颂二百零五首 其四十七","f":"词","c":["忒团圞，不相瞒。","冬不寒，腊下看。"]},{"t":"偈颂二百零五首 其四十九","f":"词","c":["不习禅，不论义，铺个破席日里睡。","想料上方兜率天，也无如此日炙背。"]},{"t":"偈颂二百零五首 其三十一","f":"词","c":["玉麒麟，铁昆仑。","金绳在渠手，归步月黄昏。"]},{"t":"偈颂二百零五首 其一七七","f":"词","c":["清净性空水，光明法界身。","依俙辨白处，便是诞生人。","不洗体，不洗尘，妙触宣明悟水因。","借问当年向去事，如何今日却来亲。","二千年前此时候，指天指地师子吼。","云门居乱思太平，打杀不妨将喂狗。","指东话西，将无作有。","恶水泼君君莫嗔，而今看你如何受。"]},{"t":"偈颂二百零五首 其一八三","f":"词","c":["作么生行，履得十成，去功业力争英雄。","刘项时，将太平。","坐亨朴懋，羲轩世人。"]},{"t":"偈颂二百零五首 其二○六","f":"七言绝句","c":["若于一切法上通，身去亦是有所得。","若于一切用处豁，落去亦是有所得。"]},{"t":"偈颂二百零五首 其十一","f":"词","c":["你也住，我也住，十方三世一时捏。","聚月醉云酣离水犀，转身触倒珊瑚树。"]},{"t":"偈颂二百零五首 其一九○","f":"五言律诗","c":["无人接得渠，贵逼马相如。","果来桥上也，记得柱头书。","无人识得渠，棋局醉樵夫。","回头斧柯烂，大海一成枯。"]},{"t":"偈颂二百零五首 其一二五","f":"词","c":["唯心唯识，平出平入。","金刀之齐，玉尺之直。","你唤甚么作三界，真个不曾遗颗粒。"]},{"t":"偈颂二百零五首 其二十九","f":"词","c":["檐头雨滴声，问你要惺惺。","直下成己事，途中作主盟。","刹刹见佛，尘尘出经。","擘开华岳连天色，放出黄河到海声。"]},{"t":"偈颂二百零五首 其二十三","f":"词","c":["露，超宗越祖。","人言渠爇返魂香，我道伊挝涂毒鼓。","苦苦，更若咬文嚼字，规行矩步。","上唱下随，前瞻后顾。","张三裹帽新有钱，富汉不是恁么做。"]},{"t":"偈颂二百零五首 其十","f":"七言律诗","c":["五月五日天中节，百草头上看生杀。","甘草黄连自苦甜，人参附子分寒热。","薰莸难昧双垂爪，滋味那瞒初偃月。","圆明了知心念閒，摩诃迦叶能分别。"]},{"t":"偈颂二百零五首 其一六○","f":"词","c":["难难难是遣情难，情尽圆明一颗寒。","大法眼，不相谩。","面前不破案山碍，直下无津识浪乾。"]},{"t":"偈颂二百零五首 其一八二","f":"楚辞体","c":["却请和尚道，三世诸佛也靠倒。","释迦师，净名老，毗耶摩竭心相照。","倦鹤夜移巢，灵蛇寒入草，正偏转侧兮妙圆兼到。"]},{"t":"偈颂二百零五首 其十七","f":"楚辞体","c":["肉团无主，空劫有家。","清白十分活计，丕平一段生涯。","月户风高兮云凝古路，星河浪静兮夜泛灵槎。","唯心成万法，化佛现千华。","快须拽鼻回香象，切忌当头触死蛇。"]},{"t":"偈颂二百零五首 其二十八","f":"词","c":["眼里拈却翳，空中那有华。","路不拾遗君子事，民无侵扰太平家。"]},{"t":"偈颂二百零五首 其三十三","f":"词","c":["人平不语，水平不流。","风定华犹落，鸟啼山更幽。","只么天真无少剩，莫于里许著丝头。"]},{"t":"偈颂二百零五首 其一一九","f":"楚辞体","c":["一人之父，百王之师。","道机有馀兮，动若四时。","寿域无疆兮，量同二仪。","大功不宰，至化无为。","妙兮虽喻，智也不知。","权挂垢衣云是佛，却装珍御复名谁。"]},{"t":"偈颂二百零五首 其二十六","f":"词","c":["身非尘聚，卓卓妙存。","心非情缘，冥冥独尊。","其体也出诸障碍，其用也得大自在。","无去无来，非显非晦。","应色应声，亡对亡待。","馒头胡饼观世音，还我当行家卖买。"]},{"t":"偈颂二百零五首 其一六四","f":"词","c":["玉壶著脚四围宽，妙处其中转侧看。","顾鉴功忘鼻孔直，津流识尽髑髅乾。","夜横河汉白，霜洗斗牛寒。"]},{"t":"偈颂二百零五首 其一二一","f":"词","c":["寒林濡露，明月濯波。","时节恁么，衲僧如何。","廓一念不见有自，极十方不见有它。","遍界通身无背面，莫教丝绪落机梭。"]},{"t":"偈颂二百零五首 其一九八","f":"七言律诗","c":["一著能回一局棋，仙即妙处只些儿。","点开活眼分生杀，不作穷忙死马医。","倒却门前刹竿著，一把推出谁藏缩。","工夫磨琢老成人，圆陀陀地无棱角。"]},{"t":"偈颂二百零五首 其一六二","f":"词","c":["只者便是，非像非镜。","谁主谁宾，何偏何正。","缝罅莫我欺无孔之槌，锱铢莫我定无星之秤。","聊将柱杖搅沧溟，令彼鱼龙知水为命。"]},{"t":"偈颂二百零五首 其七十五","f":"词","c":["不可得而有，不可得而无。","寂寂十方坐断，寥寥一境清虚。","妍丑那能瞒净镜，青黄莫我染明珠。","刹海不能关锁月，夜来流影在珊瑚。"]},{"t":"偈颂二百零五首 其六","f":"七言绝句","c":["溶溶曳曳山上云，潺潺湲湲山下水。","试问其间云水人，更于何处求诸己。"]},{"t":"偈颂二百零五首 其五十二","f":"词","c":["春雨洗园林，春风动帘箔。","百城人已归，弹指开楼阁。","入门俱是佛家风，帝网光明相映夺。"]},{"t":"偈颂二百零五首 其一五三","f":"词","c":["默默相投时节，灯灯不断光明。","其间著脚浑无地，望尽玉壶连底清。"]},{"t":"偈颂二百零五首 其一一○","f":"词","c":["百草头上平生事，闹市门前百亿身。","及尽如许闲影响，体明空劫那边人。","那边人，何所有，白云断处青山秀。","绝他缘，唯自守，结夏须教醭生口。","有说便是野干鸣，无说自然师子吼。"]},{"t":"偈颂二百零五首 其一○四","f":"七言绝句","c":["莺弄歌喉华弄妍，如许春事在门前。","道冲而用亡机者，买尽风流不著钱。"]},{"t":"偈颂二百零五首 其一○九","f":"五言绝句","c":["岭头功德眼，倦足等闲垂。","红炉一点雪，直下廓亡依。"]},{"t":"偈颂二百零五首 其一二九","f":"词","c":["功勋消，阶级尽。","尊贵不知名，威严莫得近。","子退步而就父，臣转身以合君。","机转玉轮侧，妙叶正当风。"]},{"t":"偈颂二百零五首 其十九","f":"楚辞体","c":["夤缘心，和合相，傀儡棚头呈伎俩。","打破画屏归去来，家山田地还清旷。","扫断情尘，沥乾识浪。","虚明游践兮风月一壶，梦冷转身兮雪云万丈。"]},{"t":"偈颂二百零五首 其一四○","f":"词","c":["净不涉缘，照不对物。","用无去来之相，混无彼我之心。","稳稳密密，玲玲珑珑。","宛转虚玄事不彰，明暗只在影中圆。"]},{"t":"偈颂二百零五首 其一五八","f":"词","c":["百城游遍，遍诣文殊。","不见其身，唯摩其顶。","老眼就看青嶂骨，败鞋行到白云根。"]},{"t":"偈颂二百零五首 其一五四","f":"词","c":["句里明宗则易，宗中辨的则难。","也须是到个时节，始得色转不见身。","功亡不知位。","绝怜大匠一斲泥，不犯祖师三尺鼻。","儿孙去后阿谁共守清贫，臣庶退时独自难称尊贵。"]},{"t":"偈颂二百零五首 其一○一","f":"词","c":["生灭夤缘不著人，一年才尽又逢春。","森罗借得为他用，法界浑仑是我身。","不受杂毒，自然纯真。","拈却千差亡彼此，打成一片没根尘。"]},{"t":"偈颂二百零五首 其四十四","f":"七言绝句","c":["青山不用白云朝，白云不用青山管。","云常在山山在云，青山自闲云自缓。"]},{"t":"偈颂二百零五首 其二○七","f":"楚辞体","c":["心心智通，佛佛道同。","十方圆满，八面玲珑。","施时也三乘教备，坐处也一切法空。","应供而来有不受之受，度世而出得无功之功。","动而常静，用时弥冲。","处处不乖兮水中夜月，物物斯应兮华上春风。","因缘和合而生，生不可生生。","影生于形，响生于声。","森罗万像从峥嵘，虚空廓落无亏盈。","杳杳冥冥，灵灵明明。","是其中之精，非其外之情。","见本家旷古之佛，得自己广大之经。","湛兮若存无迹像，善恶不我相随行。","物物现成观自在，人人具足常不轻。"]},{"t":"偈颂二百零五首 其八十六","f":"词","c":["鉴像谷神，云心月影。","閒閒不宰于功，历历无私于应。","莫问正偏，谁论动静。","自方自圆，谁欠谁剩。","能来异类中行，常处那伽大定。","云水丛林自恣人，果如是也须相庆。"]},{"t":"偈颂二百零五首 其九十四","f":"词","c":["大而无外，小而无内。","合虚空而无欠无馀，混万象而成团成块。","不出不在，不失不坏。","我不与物争，物不为我碍。","路逢达道人，不将语默对。","三千界里放光明，双六盘中休喝彩。"]},{"t":"偈颂二百零五首 其一八五","f":"词","c":["不得讳，有头底。","当时你带累别人，而今别人带累你。","来生我家，作业相似，针线穿联细中细。","迦叶阿难不相知，人人各自住三昧。","里许转功勋，这边得游戏，到底还须彻根蒂。","望断冥鸿没处秋，苍苍一色天连水。"]},{"t":"偈颂二百零五首 其一一七","f":"词","c":["端公问处来，径直勿迂回。","善财处处逢弥勒，弹指作声楼阁开。"]},{"t":"偈颂二百零五首 其一八○","f":"词","c":["一色是须转，大功不我居，珠走碧盘盘走珠。","直下沧溟取明月，吾家自有昆崙奴。","天宇豁空云卷雨，溪容澄澈水怀秋。"]},{"t":"偈颂二百零五首 其一七二","f":"词","c":["一头白发几回春，方信闲身似痴人。","直下放教平稳去，更将何法作根尘。","法无根尘，心无向背。","心无向背，道合自然。","道合自然也，日日好日，年年好年。","东君刀尺裁华木，付与过头杖子禅。"]},{"t":"偈颂二百零五首 其一四八","f":"词","c":["差之毫釐，失之千里。","会也打草惊蛇，不会也烧钱引鬼。","荒田不拣老俱胝，只今信手拈来底。"]},{"t":"偈颂二百零五首 其五十五","f":"词","c":["心心相印，叶叶联芳，自己光明不覆藏。","刹刹尘尘如是说，广长舌相解敷扬。"]},{"t":"偈颂二百零五首 其一三八","f":"词","c":["岁朝坐禅，万事自然。","心心绝待，佛佛现前。","清白十分江上雪，谢郎满意钓渔船。"]},{"t":"偈颂二百零五首 其五十九","f":"词","c":["一雨一晴，盖载生成。","桃华濯锦而丽，杨柳弄风而轻。","决决野泉发响，关关林鸟和鸣。","历历见闻中得妙，更嫌何处不分明。"]},{"t":"偈颂二百零五首 其九十","f":"词","c":["主中主，须辨取。","动犯威严，细看规矩。","贵不可得其名，寿不可穷其数。","四溟潮落露仙山，万里云开廓天宇。"]},{"t":"偈颂二百零五首 其一○六","f":"词","c":["清彻性空水，圆明净智身。","个中不洗体，直下了无尘。","有成佛，有降神。","有彼岸，有迷津。","哆哆和和此其始，胶胶缀缀此其因。","底时节，释迦文，恶水蓦头浇莫嗔。","何须念彼观音力，自然还著于本人。"]},{"t":"偈颂二百零五首 其一","f":"词","c":["阴极而阳生，力穷而位转。","苍龙退骨而骧，玄豹披雾而变。","要将三世佛髑髅，穿作数珠子一穿。","莫道明头暗头，真个日面月面。","直饶你斗满秤平，也输我卖贵买贱。","槃里明珠，不拨自转。"]},{"t":"偈颂二百零五首 其十五","f":"词","c":["蛇钻不入，鸟飞不度，我道人人在里许。","三更明月下西山，一阵清霜脱寒树。"]},{"t":"偈颂二百零五首 其九十六","f":"楚辞体","c":["云门老子能施设，胡饼佛祖俱超越。","哆哆和和两片皮，狤狤獠獠三寸舌。","不是特地展家风，也非投机应时节。","生铁铸成无孔锤，忒团圞兮难下楔。"]},{"t":"偈颂二百零五首 其一五一","f":"词","c":["我住汝亦住，我行汝亦行。","结制顺诸佛，禁足护众生。","金锁无须两头动，灵犀有晕中间明。","泥牛入海恰半夜，木鸡唤月看五更。","云倚山是父子，眼约眉为兄弟。","三世同参或一段合宗家之事，大千等量破微尘出自己之经。","琼林寸寸宝，旃檀片片馨。","物物头头有平出底多许，心心法法无外来底一星。","抹抹挞挞憨皮袋，跛跛挈挈常不轻。","无是无非长默默，非凡非圣独惺惺。","蒲团坐倚无他事，永日寥寥谢太平。"]},{"t":"偈颂二百零五首 其一八一","f":"七言绝句","c":["乞食浙西苏与秀，人人奉佛家家富。","收拾几成三万缗，尚自不能供众口。"]},{"t":"偈颂二百零五首 其一六六","f":"楚辞体","c":["无对无待，有兼有带。","历历物机，空空眼界。","绵绵相柱兮箭锋，恰恰相应兮函盖。","巨海饮毛，妙峰纳芥。","彼不见其有馀，我方知其无外。","普明照世约同参，补怛落伽观自在。"]},{"t":"偈颂二百零五首 其四十二","f":"词","c":["藏山于泽，藏舟于壑。","一真不可藏，怕尔满寥廓。","传家清白有风规，圆陀陀地无棱角。"]},{"t":"偈颂二百零五首 其八十九","f":"词","c":["雨从何来，不离问处。","森罗大千，出乎方寸。","照中之虚，静中之动，衲僧分上常相共。","寒露濡松夜气清，皋禽惊起月巢梦。","举刘端公问云居：雨从何来？","居云：从端公问处来。"]},{"t":"偈颂二百零五首 其九","f":"词","c":["劫前机，肘后印，用而无痕，空而不尽。","是谁造作大千，出自虚明方寸。","你侬欲去泥瘢，匠石不悭斤运。"]},{"t":"偈颂二百零五首 其一七六","f":"词","c":["家法简严，非二非三。","月来明湛水，云退露寒岩。","真机自得妙处，谁参不是文殊。","白槌后也应，千古屈瞿昙。"]},{"t":"偈颂二百零五首 其二○四","f":"词","c":["一物长灵，十方普应。","骑声跨色，超眺越听。","浩浩也能纵能横，如如也能动能静。","参饱丛林个样人，取饭不问谁家甑。","佛云常乞是清规，一切食中斯正命。"]},{"t":"偈颂二百零五首 其一八八","f":"词","c":["经归藏，禅归海。","稽首归依，合掌顶戴。","王老师，超物外。","二十年前恁么来，而今去尽閒光彩。"]},{"t":"偈颂二百零五首 其一六一","f":"词","c":["木有火伤身，人有火伤神。","木无火不生，人无火不成。","地水风火，亦复如是。","四大普周同法界，各各普周无障碍。","只者普周无碍时，自然无坏无不坏。"]},{"t":"偈颂二百零五首 其一六九","f":"词","c":["你也恁么住，我也恁么住，作业相似贫相聚。","十方无壁，四面无门。","遮丑无衣，禦寒无絮。","直下不居功，个中看转处。","采华蜂集萌不枝，卧月鸟栖无影树。"]},{"t":"偈颂二百零五首 其六十四","f":"楚辞体","c":["风不鸣条，雨不破块，会不会兮还信采。","廓廓落落兮大方无外，跛跛挈挈兮大功不宰，稳稳密密兮心安如海。"]},{"t":"偈颂二百零五首 其七十九","f":"词","c":["十方大地是我一个身便能禁足，十方众生是我一个汉方解护生。","禁足也步步不妄行，护生也心心不妄动。"]},{"t":"偈颂二百零五首 其四","f":"词","c":["生也死也，不道不道。","只知憨狗怒逐块，谁见死蛇惊出草。","著眼家林里许看，不萌枝上春阳早。"]},{"t":"偈颂二百零五首 其一四一","f":"七言绝句","c":["云无心成何处雨，蜜有味是谁家华。","一钵上方分得饭，归来香气满毗耶。"]},{"t":"偈颂二百零五首 其一五○","f":"词","c":["水不洗水，金不博金。","眼不见眼，心不用心。","不堕根境识，那涉去来今。","迷里忽然逢达磨，何曾特地作丛林。"]},{"t":"偈颂二百零五首 其九十五","f":"词","c":["里头看，勿暑寒，直下沧溟沥得乾。","我道巨鳌能俯拾，笑君沙际弄钓竿。"]},{"t":"偈颂二百零五首 其一○二","f":"楚辞体","c":["非男女之相，出有无之量。","透万机之前，超三界之上。","穷而通，简而当。","松含月兮夜寒，溪带雨而春涨。"]},{"t":"偈颂二百零五首 其一五九","f":"词","c":["地藏栽田博饭，南泉买镰割禾。","六祖负舂明历历，金牛棒钵笑呵呵。","古人得恁饱参煞，尔辈莫嫌辛苦多。"]},{"t":"偈颂二百零五首 其一三三","f":"词","c":["只者一缝大小，饱丛林汉分晓。","点头言语，丁宁摆手。","舌头狤獠不狤獠，人人脚下长安道。"]},{"t":"偈颂二百零五首 其一三六","f":"词","c":["今朝腊月二十五，衲僧一曲和云门。","谁将节奏乱孔窍，不到瘢痕伤斧斤。","舌无骨，眼有筋，方见韶阳老子能。","拍拍元来浑是令，哩鸣啰了逻鸣棱。"]}]};